import { common } from '@kit.AbilityKit';
import { preferences } from '@kit.ArkData';
import { relationalStore } from '@kit.ArkData';
import { router } from '@kit.ArkUI';

export enum ProbeEnum {
  ONE = 'ONE',
  TWO = 'TWO'
}

export class ProbeModel {
  readonly name: string;
  readonly age: number;
  constructor(name: string, age: number) {
    this.name = name;
    this.age = age;
  }
}

export class ProbeStore {
  private prefs?: preferences.Preferences;
  private rdb?: relationalStore.RdbStore;
  private record: Record<string, Object> = {};

  constructor() {
    const literal: Record<string, Object> = { 'a': 'b' };
    this.record['c'] = literal;
  }

  async init(context: common.UIAbilityContext): Promise<void> {
    this.prefs = await preferences.getPreferences(context, 'probe');
    await this.prefs.put('k', 'v');
    await this.prefs.put('n', 3);
    await this.prefs.flush();
    const value: preferences.ValueType = await this.prefs.get('k', '');
    console.info('probe value ' + String(value));
    const config: relationalStore.StoreConfig = {
      name: 'probe.db',
      securityLevel: relationalStore.SecurityLevel.S1
    };
    this.rdb = await relationalStore.getRdbStore(context, config);
    await this.rdb.executeSql('CREATE TABLE IF NOT EXISTS t (code TEXT PRIMARY KEY)');
    await this.rdb.insert('t', { 'code': 'x' });
    const rows: relationalStore.ResultSet = await this.rdb.querySql('SELECT code FROM t');
    while (rows.goToNextRow()) {
      const code: string = rows.getString(0);
      console.info('row ' + code);
    }
    rows.close();
  }

  text(value: Object | undefined): string {
    if (value === undefined || value === null) {
      return '';
    }
    return String(value);
  }

  probe(record: Record<string, Object>): string {
    const keys: string[] = Object.keys(record);
    const encoded: string = JSON.stringify(record);
    const parsed: Object | undefined = JSON.parse(encoded) as Object | undefined;
    const isList: boolean = Array.isArray(parsed);
    const parts: string[] = [];
    keys.forEach((key: string) => {
      parts.push(key);
    });
    return parts.join(',') + String(isList) + `${keys.length}`;
  }

  maps(): string {
    const counter: Map<string, number> = new Map<string, number>();
    counter.set('a', 1);
    const current: number | undefined = counter.get('a');
    return String(current === undefined ? 0 : current);
  }

  numbers(): number {
    const parsed: number = Number('7');
    return Number.isNaN(parsed) ? 0 : parsed;
  }
}

@Entry
@Component
struct Probe {
  @State items: string[] = ['a', 'b'];
  @State refreshing: boolean = false;
  @State tabIndex: number = 0;

  private refresh(): void {
    this.refreshing = false;
  }

  navigate(): void {
    router.pushUrl({ url: 'pages/Index' });
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Top, index: this.tabIndex }) {
        TabContent() {
          Column() {
            ForEach(this.items, (item: string) => {
              Text(item)
            }, (item: string) => item)
          }
        }.tabBar('Community')

        TabContent() {
          List() {
            ListItem() {
              Text('content')
            }
          }
          .onRefreshing(() => { this.refresh(); })
        }.tabBar('For You')
      }
      .onChange((index: number) => { this.tabIndex = index; })
    }
  }
}

