// Intentionally empty.
//
// This placeholder exists because the scaffold probe page could not be removed
// from the workspace with the restricted shell available to this agent. It holds
// no declarations, is not registered in main_pages.json and is never imported.

/*
 * Domain model for the personalized Home feed.
 *
 * The Home surface is made of two tabs:
 *
 *   - Community: a date grouped editorial feed served by the remote editorial
 *     service. It supports paging backwards one logical day at a time.
 *   - For You:   a personalized feed whose recommendation groups are derived by
 *     the application from the reader's saved interests, reading activity and
 *     saved articles. The result is cached per calendar date and feed language.
 *
 * Both tabs share the same presentation vocabulary (phase, empty reason and
 * recovery action) so that the empty / loading / content / error presentations
 * stay mutually coherent for every tab.
 */

/** The two tabs exposed by the Home surface. */
export enum HomeTab {
  COMMUNITY = 'COMMUNITY',
  FOR_YOU = 'FOR_YOU'
}

/**
 * The personalization choice captured by feed onboarding. The choice decides the
 * initial Home tab and is persisted, so later visits land on the same tab.
 */
export enum HomePreference {
  COMMUNITY = 'COMMUNITY',
  PERSONALIZED = 'PERSONALIZED'
}

/**
 * The recommendation groups produced for the For You tab. The order is the order
 * in which the groups are presented.
 */
export enum ForYouModuleType {
  BASED_ON_INTEREST = 'BASED_ON_INTEREST',
  BECAUSE_YOU_READ = 'BECAUSE_YOU_READ',
  CONTINUE_READING = 'CONTINUE_READING'
}

/** The editorial modules served for a Community day. */
export enum CommunityModuleType {
  FEATURED_ARTICLE = 'FEATURED_ARTICLE',
  NEWS = 'NEWS',
  TOP_READ = 'TOP_READ',
  PIC_OF_THE_DAY = 'PIC_OF_THE_DAY',
  ARTICLE = 'ARTICLE'
}

/** Card kinds that can be rendered inside a feed. */
export enum FeedCardType {
  DAY_HEADER = 'DAY_HEADER',
  FEATURED_ARTICLE = 'FEATURED_ARTICLE',
  NEWS = 'NEWS',
  TOP_READ = 'TOP_READ',
  PIC_OF_THE_DAY = 'PIC_OF_THE_DAY',
  BASED_ON_INTEREST = 'BASED_ON_INTEREST',
  BECAUSE_YOU_READ = 'BECAUSE_YOU_READ',
  CONTINUE_READING = 'CONTINUE_READING',
  ARTICLE = 'ARTICLE'
}

/** Presentation phase of a single Home tab. */
export enum FeedPhase {
  IDLE = 'idle',
  LOADING = 'loading',
  CONTENT = 'content',
  CONTENT_WITH_INLINE_ERROR = 'content_with_inline_error',
  EMPTY = 'empty',
  ERROR = 'error'
}

/** Why a tab has no content. Empty reason is only meaningful while empty. */
export enum FeedEmptyReason {
  NONE = 'NONE',
  NO_DATA = 'NO_DATA',
  ALL_MODULES_HIDDEN = 'ALL_MODULES_HIDDEN'
}

/** The action offered by an empty or errored tab. */
export enum FeedRecoveryAction {
  NONE = 'NONE',
  RETRY = 'RETRY',
  OPEN_COMMUNITY_MODULES = 'OPEN_COMMUNITY_MODULES',
  OPEN_FOR_YOU_MODULES = 'OPEN_FOR_YOU_MODULES',
  CUSTOMIZE_INTERESTS = 'CUSTOMIZE_INTERESTS',
  RETURN_TO_COMMUNITY = 'RETURN_TO_COMMUNITY'
}

/** The two independent module visibility groups offered by feed settings. */
export enum FeedSettingsTarget {
  COMMUNITY_MODULES = 'COMMUNITY_MODULES',
  FOR_YOU_MODULES = 'FOR_YOU_MODULES'
}

/** What triggered a feed request. */
export enum FeedLoadSource {
  INITIAL = 'INITIAL',
  LOAD_MORE = 'LOAD_MORE',
  RETRY = 'RETRY',
  RETRY_MORE = 'RETRY_MORE',
  REFRESH = 'REFRESH',
  RESUME = 'RESUME',
  LANGUAGE_CHANGED = 'LANGUAGE_CHANGED'
}

/** Activity result codes returned by the interest editor. */
export enum FeedActivityResult {
  RESULT_CANCELED = 0,
  RESULT_OK = -1,
  RESULT_INTERESTS_UPDATED = 100
}

/* ------------------------------------------------------------------ *
 * Value helpers. Feed content arrives from remote leaves and from the
 * persisted snapshot as loosely typed values, so every read is funnelled
 * through a coercion that always yields a usable value.
 * ------------------------------------------------------------------ */

/** Reads a loosely typed value as text. */
export function textOf(value: Object | undefined): string {
  if (value === undefined || value === null) {
    return '';
  }
  const encoded: string = JSON.stringify(value);
  if (encoded.length > 1 && encoded.charAt(0) === '"' && encoded.charAt(encoded.length - 1) === '"') {
    return encoded.substring(1, encoded.length - 1);
  }
  return encoded;
}

/** Reads a loosely typed value as a number. */
export function numberOf(value: Object | undefined, fallback: number): number {
  if (value === undefined || value === null) {
    return fallback;
  }
  const encoded: string = JSON.stringify(value);
  const parsed: number = Number(encoded);
  return Number.isNaN(parsed) ? fallback : parsed;
}

/** Reads a loosely typed value as a boolean. */
export function booleanOf(value: Object | undefined, fallback: boolean): boolean {
  if (value === undefined || value === null) {
    return fallback;
  }
  const encoded: string = JSON.stringify(value);
  if (encoded === 'true') {
    return true;
  }
  if (encoded === 'false') {
    return false;
  }
  return fallback;
}

/** Reads a loosely typed value as an array. */
export function arrayOf(value: Object | undefined): Object[] {
  if (value === undefined || value === null) {
    return [];
  }
  const encoded: string = JSON.stringify(value);
  const parsed: Object | undefined = JSON.parse(encoded) as Object | undefined;
  if (parsed === undefined || parsed === null) {
    return [];
  }
  if (Array.isArray(parsed)) {
    return parsed as Object[];
  }
  return [parsed];
}

/** Reads a loosely typed value as a keyed record. Returns undefined for scalars and lists. */
export function recordOf(value: Object | undefined): Record<string, Object> | undefined {
  if (value === undefined || value === null) {
    return undefined;
  }
  const encoded: string = JSON.stringify(value);
  if (encoded.length === 0 || encoded.charAt(0) === '[' || encoded.charAt(0) === '"') {
    return undefined;
  }
  const parsed: Object | undefined = JSON.parse(encoded) as Object | undefined;
  if (parsed === undefined || parsed === null || Array.isArray(parsed)) {
    return undefined;
  }
  return parsed as Record<string, Object>;
}

/** Reads a loosely typed value as a list of strings. */
export function textListOf(value: Object | undefined): string[] {
  const raw: Object[] = arrayOf(value);
  const result: string[] = [];
  for (let index = 0; index < raw.length; index++) {
    const entry: string = textOf(raw[index]).trim();
    if (entry.length > 0) {
      result.push(entry);
    }
  }
  return result;
}

/* ------------------------------------------------------------------ *
 * Enum coercion.
 * ------------------------------------------------------------------ */

export function homeTabOf(value: string): HomeTab | undefined {
  const normalized: string = value.trim().toUpperCase();
  if (normalized === HomeTab.COMMUNITY) {
    return HomeTab.COMMUNITY;
  }
  if (normalized === HomeTab.FOR_YOU) {
    return HomeTab.FOR_YOU;
  }
  return undefined;
}

export function homePreferenceOf(value: string): HomePreference {
  const normalized: string = value.trim().toUpperCase();
  return normalized === HomePreference.PERSONALIZED ? HomePreference.PERSONALIZED : HomePreference.COMMUNITY;
}

/** The initial Home tab implied by a persisted personalization choice. */
export function homeTabForPreference(preference: HomePreference): HomeTab {
  return preference === HomePreference.PERSONALIZED ? HomeTab.FOR_YOU : HomeTab.COMMUNITY;
}

export function feedPhaseOf(value: string): FeedPhase {
  const normalized: string = value.trim().toLowerCase();
  if (normalized === FeedPhase.LOADING) {
    return FeedPhase.LOADING;
  }
  if (normalized === FeedPhase.CONTENT) {
    return FeedPhase.CONTENT;
  }
  if (normalized === FeedPhase.CONTENT_WITH_INLINE_ERROR) {
    return FeedPhase.CONTENT_WITH_INLINE_ERROR;
  }
  if (normalized === FeedPhase.EMPTY) {
    return FeedPhase.EMPTY;
  }
  if (normalized === FeedPhase.ERROR) {
    return FeedPhase.ERROR;
  }
  return FeedPhase.IDLE;
}

export function feedCardTypeOf(value: string): FeedCardType {
  const normalized: string = value.trim().toUpperCase();
  const known: string[] = [
    FeedCardType.DAY_HEADER, FeedCardType.FEATURED_ARTICLE, FeedCardType.NEWS,
    FeedCardType.TOP_READ, FeedCardType.PIC_OF_THE_DAY, FeedCardType.BASED_ON_INTEREST,
    FeedCardType.BECAUSE_YOU_READ, FeedCardType.CONTINUE_READING, FeedCardType.ARTICLE
  ];
  for (let index = 0; index < known.length; index++) {
    if (known[index] === normalized) {
      return FeedCardType[known[index] as keyof typeof FeedCardType];
    }
  }
  return FeedCardType.ARTICLE;
}

export function isDayHeader(type: FeedCardType): boolean {
  return type === FeedCardType.DAY_HEADER;
}

/**
 * The module a card belongs to. Day headers group a Community day and therefore
 * do not belong to any editorial module.
 */
export function moduleTypeOfCard(type: FeedCardType): string {
  return isDayHeader(type) ? '' : `${type}`;
}

export function allForYouModuleTypes(): string[] {
  return [ForYouModuleType.BASED_ON_INTEREST, ForYouModuleType.BECAUSE_YOU_READ, ForYouModuleType.CONTINUE_READING];
}

export function allCommunityModuleTypes(): string[] {
  return [
    CommunityModuleType.FEATURED_ARTICLE, CommunityModuleType.NEWS,
    CommunityModuleType.TOP_READ, CommunityModuleType.PIC_OF_THE_DAY, CommunityModuleType.ARTICLE
  ];
}

export function isForYouModuleType(value: string): boolean {
  const known: string[] = allForYouModuleTypes();
  return known.indexOf(value) >= 0;
}

/* ------------------------------------------------------------------ *
 * Feed content.
 * ------------------------------------------------------------------ */

/** A single renderable feed item. */
export class FeedCard {
  readonly type: FeedCardType;
  readonly identifier: string;
  readonly title: string;
  readonly logicalAge: number;
  readonly language: string;

  constructor(type: FeedCardType, identifier: string, title: string, logicalAge: number, language: string) {
    this.type = type;
    this.identifier = identifier;
    this.title = title.length > 0 ? title : identifier;
    this.logicalAge = logicalAge;
    this.language = language;
  }

  /** Stable identity used for de-duplication and for restoring a hidden card. */
  token(): string {
    return this.identifier.length > 0 ? `${this.type}:${this.identifier}` : `${this.type}`;
  }

  /** Identity compared against the persisted hidden card list. */
  hideKey(): string {
    return this.identifier.length > 0 ? this.identifier : `${this.type}`;
  }

  /** Identity that also encodes the logical day, used to restore an exact position. */
  positionKey(): string {
    return `${this.logicalAge}#${this.token()}`;
  }
}

/** Parses a `TYPE` or `TYPE:identifier` token into a card. */
export function feedCardFromToken(token: string, logicalAge: number, language: string): FeedCard {
  const trimmed: string = token.trim();
  const separator: number = trimmed.indexOf(':');
  if (separator < 0) {
    return new FeedCard(feedCardTypeOf(trimmed), '', trimmed, logicalAge, language);
  }
  const rawType: string = trimmed.substring(0, separator);
  const identifier: string = trimmed.substring(separator + 1);
  return new FeedCard(feedCardTypeOf(rawType), identifier, identifier, logicalAge, language);
}

/** A recommendation group rendered by the For You tab. */
export class FeedModule {
  readonly type: string;
  readonly cards: FeedCard[];

  constructor(type: string, cards: FeedCard[]) {
    this.type = type;
    this.cards = cards;
  }

  visibleCards(hiddenCards: string[]): FeedCard[] {
    const result: FeedCard[] = [];
    for (let index = 0; index < this.cards.length; index++) {
      if (hiddenCards.indexOf(this.cards[index].hideKey()) < 0) {
        result.push(this.cards[index]);
      }
    }
    return result;
  }

  /** A module survives filtering while it still shows at least one card. */
  hasVisibleCard(hiddenCards: string[]): boolean {
    return this.visibleCards(hiddenCards).length > 0;
  }
}

/** Groups a flat card list into modules, preserving first appearance order. */
export function feedModulesFromCards(cards: FeedCard[]): FeedModule[] {
  const modules: FeedModule[] = [];
  for (let index = 0; index < cards.length; index++) {
    const card: FeedCard = cards[index];
    const type: string = moduleTypeOfCard(card.type);
    if (type.length === 0) {
      continue;
    }
    let target: FeedModule | undefined = undefined;
    for (let scan = 0; scan < modules.length; scan++) {
      if (modules[scan].type === type) {
        target = modules[scan];
        break;
      }
    }
    if (target === undefined) {
      modules.push(new FeedModule(type, [card]));
    } else {
      target.cards.push(card);
    }
  }
  return modules;
}

/* ------------------------------------------------------------------ *
 * Tab state.
 * ------------------------------------------------------------------ */

const PHASE_HISTORY_LIMIT = 16;

/** Mutable presentation state of the Community tab. */
export class CommunityFeedState {
  phase: FeedPhase = FeedPhase.IDLE;
  /** Cards exactly as received, before hidden card filtering. */
  backingCards: FeedCard[] = [];
  /** Cards after hidden card and hidden module filtering. */
  cards: FeedCard[] = [];
  language: string = '';
  date: string = '';
  /** The logical day the next request will ask for. Only advances on success. */
  nextLogicalAge: number = 0;
  /** The logical day of the request that failed, or -1. */
  failedLogicalAge: number = -1;
  retryAvailable: boolean = false;
  inlineError: boolean = false;
  loading: boolean = false;
  emptyReason: FeedEmptyReason = FeedEmptyReason.NONE;
  recoveryAction: FeedRecoveryAction = FeedRecoveryAction.NONE;
  lastSource: string = '';
  attempts: number = 0;
  phaseHistory: string[] = [];

  constructor() {
    this.phaseHistory.push(FeedPhase.IDLE);
  }

  hasContent(): boolean {
    return this.cards.length > 0;
  }

  newestLogicalAge(): number {
    let newest: number = -1;
    for (let index = 0; index < this.backingCards.length; index++) {
      if (isDayHeader(this.backingCards[index].type)) {
        continue;
      }
      if (this.backingCards[index].logicalAge > newest) {
        newest = this.backingCards[index].logicalAge;
      }
    }
    return newest;
  }

  pushHistory(phase: FeedPhase): void {
    const last: string = this.phaseHistory.length > 0 ? this.phaseHistory[this.phaseHistory.length - 1] : '';
    if (last !== phase) {
      this.phaseHistory.push(phase);
      if (this.phaseHistory.length > PHASE_HISTORY_LIMIT) {
        this.phaseHistory.shift();
      }
    }
  }

  /** Enters the loading presentation while keeping already available content. */
  beginLoading(source: FeedLoadSource): void {
    this.loading = true;
    this.lastSource = source;
    this.attempts++;
    this.pushHistory(FeedPhase.LOADING);
    if (!this.hasContent()) {
      this.phase = FeedPhase.LOADING;
      this.emptyReason = FeedEmptyReason.NONE;
      this.recoveryAction = FeedRecoveryAction.NONE;
      this.retryAvailable = false;
      this.inlineError = false;
    }
  }

  endLoading(): void {
    this.loading = false;
  }

  recordPhase(phase: FeedPhase): void {
    this.phase = phase;
    this.pushHistory(phase);
  }

  reset(language: string, date: string): void {
    this.backingCards = [];
    this.cards = [];
    this.language = language;
    this.date = date;
    this.phase = FeedPhase.IDLE;
    this.pushHistory(FeedPhase.IDLE);
    this.nextLogicalAge = 0;
    this.failedLogicalAge = -1;
    this.retryAvailable = false;
    this.inlineError = false;
    this.loading = false;
    this.emptyReason = FeedEmptyReason.NONE;
    this.recoveryAction = FeedRecoveryAction.NONE;
  }

  toRecord(): Record<string, Object> {
    const record: Record<string, Object> = {
      'phase': this.phase,
      'cards': cardTokens(this.cards),
      'language': this.language,
      'date': this.date,
      'cardCount': this.cards.length,
      'hasContent': this.hasContent(),
      'loading': this.loading,
      'retryAvailable': this.retryAvailable,
      'inlineError': this.inlineError,
      'emptyReason': this.emptyReason,
      'recoveryAction': this.recoveryAction,
      'lastSource': this.lastSource,
      'attempts': this.attempts,
      'phaseHistory': this.phaseHistory,
      'hiddenModuleTypes': visibleModuleTypes(this.backingCards, [], [])
    };
    return record;
  }
}

/** Mutable presentation state of the For You tab. */
export class ForYouFeedState {
  phase: FeedPhase = FeedPhase.IDLE;
  /** Recommendation groups exactly as derived, before filtering. */
  backingModules: FeedModule[] = [];
  /** Recommendation groups after hidden card and hidden module filtering. */
  modules: FeedModule[] = [];
  language: string = '';
  date: string = '';
  /** The batch the next request will ask for. Only advances on success. */
  batchIndex: number = 0;
  /** The batch of the request that failed, or -1. */
  failedBatch: number = -1;
  retryAvailable: boolean = false;
  inlineError: boolean = false;
  loading: boolean = false;
  /** True when the tab is showing the stable daily result for its language. */
  stableResult: boolean = false;
  emptyReason: FeedEmptyReason = FeedEmptyReason.NONE;
  recoveryAction: FeedRecoveryAction = FeedRecoveryAction.NONE;
  lastSource: string = '';
  attempts: number = 0;
  phaseHistory: string[] = [];

  constructor() {
    this.phaseHistory.push(FeedPhase.IDLE);
  }

  hasContent(): boolean {
    return this.modules.length > 0;
  }

  pushHistory(phase: FeedPhase): void {
    const last: string = this.phaseHistory.length > 0 ? this.phaseHistory[this.phaseHistory.length - 1] : '';
    if (last !== phase) {
      this.phaseHistory.push(phase);
      if (this.phaseHistory.length > PHASE_HISTORY_LIMIT) {
        this.phaseHistory.shift();
      }
    }
  }

  beginLoading(source: FeedLoadSource): void {
    this.loading = true;
    this.lastSource = source;
    this.attempts++;
    this.pushHistory(FeedPhase.LOADING);
    if (!this.hasContent()) {
      this.phase = FeedPhase.LOADING;
      this.emptyReason = FeedEmptyReason.NONE;
      this.recoveryAction = FeedRecoveryAction.NONE;
      this.retryAvailable = false;
      this.inlineError = false;
    }
  }

  endLoading(): void {
    this.loading = false;
  }

  recordPhase(phase: FeedPhase): void {
    this.phase = phase;
    this.pushHistory(phase);
  }

  reset(language: string, date: string): void {
    this.backingModules = [];
    this.modules = [];
    this.language = language;
    this.date = date;
    this.phase = FeedPhase.IDLE;
    this.pushHistory(FeedPhase.IDLE);
    this.batchIndex = 0;
    this.failedBatch = -1;
    this.retryAvailable = false;
    this.inlineError = false;
    this.loading = false;
    this.stableResult = false;
    this.emptyReason = FeedEmptyReason.NONE;
    this.recoveryAction = FeedRecoveryAction.NONE;
  }

  toRecord(hiddenCards: string[], hiddenModules: string[]): Record<string, Object> {
    const record: Record<string, Object> = {
      'phase': this.phase,
      'modules': moduleTypes(this.modules),
      'moduleTypes': moduleTypes(this.modules),
      'cards': moduleCardTokens(this.modules),
      'moduleCardTokens': moduleCardTokens(this.modules),
      'language': this.language,
      'date': this.date,
      'moduleCount': this.modules.length,
      'backingModuleCount': this.backingModules.length,
      'hasContent': this.hasContent(),
      'loading': this.loading,
      'retryAvailable': this.retryAvailable,
      'inlineError': this.inlineError,
      'stableResult': this.stableResult,
      'emptyReason': this.emptyReason,
      'recoveryAction': this.recoveryAction,
      'lastSource': this.lastSource,
      'attempts': this.attempts,
      'phaseHistory': this.phaseHistory,
      'batchIndex': this.batchIndex,
      'failedBatch': this.failedBatch,
      'settingsTarget': FeedSettingsTarget.FOR_YOU_MODULES,
      'filteredBy': hiddenModuleNames(this.backingModules, this.modules, hiddenCards, hiddenModules)
    };
    return record;
  }
}

/* ------------------------------------------------------------------ *
 * Serialization helpers shared by the two tab states.
 * ------------------------------------------------------------------ */

/** `TYPE:identifier` tokens for a flat card list. */
export function cardTokens(cards: FeedCard[]): string[] {
  const result: string[] = [];
  for (let index = 0; index < cards.length; index++) {
    result.push(cards[index].token());
  }
  return result;
}

/** Module types currently presented, in order. */
export function moduleTypes(modules: FeedModule[]): string[] {
  const result: string[] = [];
  for (let index = 0; index < modules.length; index++) {
    result.push(modules[index].type);
  }
  return result;
}

/** Flat card tokens across every presented module. */
export function moduleCardTokens(modules: FeedModule[]): string[] {
  const result: string[] = [];
  for (let index = 0; index < modules.length; index++) {
    const cards: FeedCard[] = modules[index].cards;
    for (let cardIndex = 0; cardIndex < cards.length; cardIndex++) {
      result.push(cards[cardIndex].token());
    }
  }
  return result;
}

/** Every module type present in a backing card list. */
export function visibleModuleTypes(cards: FeedCard[], hiddenCards: string[], hiddenModules: string[]): string[] {
  return moduleTypes(feedModulesFromCards(cards).filter((module: FeedModule) => {
    if (hiddenModules.indexOf(module.type) >= 0) {
      return false;
    }
    return module.hasVisibleCard(hiddenCards);
  }));
}

function moduleCardKeys(module: FeedModule): string {
  return moduleCardTokens([module]).join('|');
}

/**
 * Describes why a presented module list differs from the backing module list.
 * Backing modules are filtered, never deleted, so this is the record that proves
 * a hide action only changed presentation.
 */
export function filteredBy(
  backing: FeedModule[], presented: FeedModule[], hiddenCards: string[], hiddenModules: string[]
): string[] {
  const reasons: string[] = [];
  for (let index = 0; index < backing.length; index++) {
    if (hiddenModules.indexOf(backing[index].type) >= 0) {
      reasons.push(`${backing[index].type}:module`);
    } else if (moduleCardKeys(backing[index]) !== moduleCardKeys(presented[index])) {
      reasons.push(`${backing[index].type}:card`);
    }
  }
  return reasons;
}

function hiddenModuleNames(
  backing: FeedModule[], presented: FeedModule[], hiddenCards: string[], hiddenModules: string[]
): string[] {
  return filteredBy(backing, presented, hiddenCards, hiddenModules);
}

/** Calendar date helper. Feed content is always scoped by an ISO calendar day. */
export class FeedClock {
  private fixedToday: string;

  constructor(fixedToday: string) {
    this.fixedToday = normalizeDate(fixedToday, systemDate());
  }

  today(): string {
    return this.fixedToday;
  }
}

/** Normalizes a date token, mapping the relative forms onto the clock's day. */
export function normalizeDate(value: string, today: string): string {
  const trimmed: string = value.trim();
  if (trimmed.length === 0) {
    return today;
  }
  const lowered: string = trimmed.toLowerCase();
  if (lowered === 'today' || lowered === 'now' || lowered === 'current') {
    return today;
  }
  return trimmed;
}

/** The device's current calendar day in ISO form. */
export function systemDate(): string {
  const now: Date = new Date();
  const year: number = now.getFullYear();
  const month: number = now.getMonth() + 1;
  const day: number = now.getDate();
  const paddedMonth: string = month < 10 ? `0${month}` : `${month}`;
  const paddedDay: string = day < 10 ? `0${day}` : `${day}`;
  return `${year}-${paddedMonth}-${paddedDay}`;
}

import {
  arrayOf, booleanOf, FeedCard, feedCardFromToken, feedCardTypeOf, FeedModule, feedModulesFromCards,
  isDayHeader, numberOf, recordOf, textListOf, textOf
} from './FeedDomain';

/**
 * The snapshot the page host injects when it mounts the Home surface.
 *
 * A snapshot is made of a `state` record (what the surface is showing right now)
 * and a `persistence` record (what was written to durable storage). Both carry
 * loosely typed values, so every read goes through {@link FeedSnapshot} which
 * resolves the first alias that is present and always returns a usable value.
 */
export class FeedSnapshot {
  private readonly state: Record<string, Object>;
  private readonly persistence: Record<string, Object>;

  constructor(state: Record<string, Object> | undefined, persistence: Record<string, Object> | undefined) {
    this.state = state === undefined ? {} : state;
    this.persistence = persistence === undefined ? {} : persistence;
  }

  private raw(keys: string[]): Object | undefined {
    let result: Object | undefined = undefined;
    for (let index = 0; index < keys.length; index++) {
      const value: Object | undefined = this.state[keys[index]];
      if (value !== undefined && value !== null) {
        result = value;
        break;
      }
    }
    if (result !== undefined) {
      return result;
    }
    for (let index = 0; index < keys.length; index++) {
      const value: Object | undefined = this.persistence[keys[index]];
      if (value !== undefined && value !== null) {
        return value;
      }
    }
    return undefined;
  }

  text(keys: string[]): string {
    return textOf(this.raw(keys)).trim();
  }

  number(keys: string[], fallback: number): number {
    return numberOf(this.raw(keys), fallback);
  }

  flag(keys: string[], fallback: boolean): boolean {
    return booleanOf(this.raw(keys), fallback);
  }

  list(keys: string[]): string[] {
    return textListOf(this.raw(keys));
  }

  record(keys: string[]): Record<string, Object> | undefined {
    return recordOf(this.raw(keys));
  }

  items(keys: string[]): Object[] {
    return arrayOf(this.raw(keys));
  }

  present(keys: string[]): boolean {
    return this.raw(keys) !== undefined;
  }

  /** The state half of the snapshot, used when a value is only meaningful live. */
  getState(): Record<string, Object> {
    return this.state;
  }

  /** The persistence half of the snapshot. */
  getPersistence(): Record<string, Object> {
    return this.persistence;
  }
}

/* ------------------------------------------------------------------ *
 * Parsing of loosely typed feed payloads.
 * ------------------------------------------------------------------ */

/** Parses a list of `TYPE[:identifier]` tokens into cards for one logical day. */
export function parseCards(payload: Object | undefined, logicalAge: number, language: string): FeedCard[] {
  const raw: Object[] = arrayOf(payload);
  const cards: FeedCard[] = [];
  for (let index = 0; index < raw.length; index++) {
    const record: Record<string, Object> | undefined = recordOf(raw[index]);
    if (record !== undefined) {
      const card: FeedCard | undefined = cardFromRecord(record, logicalAge, language);
      if (card !== undefined) {
        cards.push(card);
      }
      continue;
    }
    const token: string = textOf(raw[index]).trim();
    if (token.length > 0) {
      cards.push(feedCardFromToken(token, logicalAge, language));
    }
  }
  return cards;
}

function cardFromRecord(record: Record<string, Object>, logicalAge: number, language: string): FeedCard | undefined {
  const type: string = textOf(record['type']).trim();
  const identifier: string = textOf(record['id']).trim().length > 0 ? textOf(record['id']).trim() : textOf(record['title']).trim();
  if (type.length === 0 && identifier.length === 0) {
    return undefined;
  }
  const cardType: string = type.length > 0 ? type : 'ARTICLE';
  return new FeedCard(feedCardTypeOf(cardType), identifier, identifier, logicalAge, language);
}

/**
 * Parses a recommendation payload into modules.
 *
 * Accepted shapes:
 *   - a flat list of `MODULE[:identifier]` card tokens
 *   - a list of `{ type, cards: [...] }` records
 *   - a `{ MODULE: [identifier, ...] }` map
 *   - a `{ MODULE: 'identifier' }` map
 */
export function parseModules(payload: Object | undefined, language: string): FeedModule[] {
  const raw: Object[] = arrayOf(payload);
  const modules: FeedModule[] = [];
  for (let index = 0; index < raw.length; index++) {
    const record: Record<string, Object> | undefined = recordOf(raw[index]);
    if (record !== undefined && record['type'] !== undefined) {
      const type: string = textOf(record['type']).trim();
      const cards: FeedCard[] = parseCards(record['cards'], 0, language);
      modules.push(new FeedModule(type, cards));
      continue;
    }
    if (record !== undefined) {
      const keys: string[] = Object.keys(record);
      for (let keyIndex = 0; keyIndex < keys.length; keyIndex++) {
        const type: string = keys[keyIndex];
        const cards: FeedCard[] = parseCards(record[type], 0, language);
        if (cards.length === 0) {
          const single: string = textOf(record[type]).trim();
          if (single.length > 0) {
            cards.push(feedCardFromToken(`${type}:${single}`, 0, language));
          }
        }
        modules.push(new FeedModule(type, cards));
      }
      continue;
    }
    const token: string = textOf(raw[index]).trim();
    if (token.length === 0) {
      continue;
    }
    const separator: number = token.indexOf(':');
    if (separator < 0) {
      const type: string = token;
      modules.push(new FeedModule(type, [feedCardFromToken(token, 0, language)]));
      continue;
    }
    const card: FeedCard = feedCardFromToken(token, 0, language);
    modules.push(new FeedModule(`${card.type}`, [card]));
  }
  return modules;
}

const MODULE_PAYLOAD_KEYS: string[] = [
  'modules', 'moduleList', 'items', 'recommendations', 'content', 'backingModules', 'entries', 'groups'
];

const LANGUAGE_PAYLOAD_KEYS: string[] = ['byLanguage', 'modulesByLanguage', 'perLanguage', 'languagesByCode'];

/**
 * Extracts the recommendation payload a For You cache entry holds for `language`.
 *
 * A cache entry is only usable when it was written for the same calendar date
 * and the requested language, so both the date and the language keyed payload
 * have to line up before any module is restored.
 */
export function modulesFromCacheEntry(entry: Record<string, Object>, language: string): FeedModule[] {
  const direct: Record<string, Object> | undefined = recordOf(entry[language]);
  if (direct !== undefined) {
    const keyed: FeedModule[] = parseModules(direct[language], language);
    if (keyed.length > 0) {
      return keyed;
    }
    return parseModules(entry[language], language);
  }
  for (let index = 0; index < LANGUAGE_PAYLOAD_KEYS.length; index++) {
    const scoped: Record<string, Object> | undefined = recordOf(entry[LANGUAGE_PAYLOAD_KEYS[index]]);
    if (scoped === undefined) {
      continue;
    }
    const scopedDirect: Object | undefined = scoped[language];
    if (scopedDirect !== undefined) {
      return parseModules(scopedDirect, language);
    }
  }
  for (let index = 0; index < MODULE_PAYLOAD_KEYS.length; index++) {
    const payload: Object | undefined = entry[MODULE_PAYLOAD_KEYS[index]];
    if (payload !== undefined) {
      const parsed: FeedModule[] = parseModules(payload, language);
      if (parsed.length > 0) {
        return parsed;
      }
    }
  }
  return [];
}

/** Languages a For You cache entry holds a payload for. */
export function languagesOfCacheEntry(entry: Record<string, Object>): string[] {
  const result: string[] = [];
  const declared: string[] = textListOf(entry['languages']);
  for (let index = 0; index < declared.length; index++) {
    if (result.indexOf(declared[index]) < 0) {
      result.push(declared[index]);
    }
  }
  const keys: string[] = ['byLanguage', 'modulesByLanguage', 'perLanguage'];
  for (let keyIndex = 0; keyIndex < keys.length; keyIndex++) {
    const scoped: Record<string, Object> | undefined = recordOf(entry[keys[keyIndex]]);
    if (scoped === undefined) {
      continue;
    }
    const scopedKeys: string[] = Object.keys(scoped);
    for (let index = 0; index < scopedKeys.length; index++) {
      if (result.indexOf(scopedKeys[index]) < 0) {
        result.push(scopedKeys[index]);
      }
    }
  }
  return result;
}

/**
 * Inserts the day header that groups the editorial modules of `logicalAge`, so
 * Community content stays grouped by calendar day while older days are added.
 */
export function withDayHeader(cards: FeedCard[], logicalAge: number, language: string): FeedCard[] {
  const header: FeedCard = new FeedCard(feedCardTypeOf('DAY_HEADER'), `${logicalAge}`, `${logicalAge}`, logicalAge, language);
  const result: FeedCard[] = [header];
  for (let index = 0; index < cards.length; index++) {
    result.push(cards[index]);
  }
  return result;
}

/** True when the list already opens with the header of `logicalAge`. */
export function startsWithDayHeader(cards: FeedCard[], logicalAge: number): boolean {
  if (cards.length === 0) {
    return false;
  }
  const first: FeedCard = cards[0];
  return isDayHeader(first.type) && first.logicalAge === logicalAge;
}

import { ExploreEffect, ExploreLeaf } from '../integration/ExplorePageIntegration';
import { FeedCard, FeedLoadSource, FeedTabSurface, parseTokensSafe, textOf } from './FeedDomain';

/** Raised by a feed leaf when a request cannot be served. */
export class FeedServiceException extends Error {
  readonly kind: string;

  constructor(kind: string) {
    super(kind);
    this.kind = kind;
  }
}

/** A single Community request for one logical day. */
export class CommunityRequest {
  readonly language: string;
  readonly date: string;
  readonly logicalAge: number;
  readonly attempt: number;
  readonly attemptForLogicalAge: number;
  readonly source: FeedLoadSource;

  constructor(language: string, date: string, logicalAge: number, attempt: number,
    attemptForLogicalAge: number, source: FeedLoadSource) {
    this.language = language;
    this.date = date;
    this.logicalAge = logicalAge;
    this.attempt = attempt;
    this.attemptForLogicalAge = attemptForLogicalAge;
    this.source = source;
  }

  scope(): string {
    return `community:${this.logicalAge}`;
  }
}

/** A single For You request for one daily batch. */
export class ForYouRequest {
  readonly language: string;
  readonly date: string;
  readonly batch: number;
  readonly attempt: number;
  readonly source: FeedLoadSource;

  constructor(language: string, date: string, batch: number, attempt: number, source: FeedLoadSource) {
    this.language = language;
    this.date = date;
    this.batch = batch;
    this.attempt = attempt;
    this.source = source;
  }

  scope(): string {
    return `for_you:${this.batch}`;
  }
}

/** A served Community day. */
export class CommunityPage {
  readonly logicalAge: number;
  readonly date: string;
  readonly cards: FeedCard[];
  readonly hasMore: boolean;

  constructor(logicalAge: number, date: string, cards: FeedCard[], hasMore: boolean) {
    this.logicalAge = logicalAge;
    this.date = date;
    this.cards = cards;
    this.hasMore = hasMore;
  }
}

/** A served For You batch. */
export class ForYouPage {
  readonly date: string;
  readonly language: string;
  readonly batch: number;
  readonly hasMore: boolean;
  /** Article titles ranked by the recommendation service, in rank order. */
  readonly rankedTitles: string[];

  constructor(date: string, language: string, batch: number, hasMore: boolean, rankedTitles: string[]) {
    this.date = date;
    this.language = language;
    this.batch = batch;
    this.hasMore = hasMore;
    this.rankedTitles = rankedTitles;
  }
}

/* ------------------------------------------------------------------ *
 * Scripted responses.
 *
 * The editorial and recommendation services are leaf boundaries: they are
 * reached only through {@link ExploreLeaf}. Whatever a boundary answers is
 * recorded by the host and handed back to the application as a script, which the
 * service replays one page per request. Failures are one shot, so a retry of the
 * same logical day or batch reaches the service again instead of replaying the
 * same failure.
 * ------------------------------------------------------------------ */

/** One scripted answer of a feed leaf. */
export class ScriptedPage {
  failed: boolean = false;
  error: string = '';
  tokens: string[] = [];

  constructor() {
  }

  static failure(kind: string): ScriptedPage {
    const page: ScriptedPage = new ScriptedPage();
    page.failed = true;
    page.error = kind.length > 0 ? kind : 'IOException';
    return page;
  }

  static content(tokens: string[]): ScriptedPage {
    const page: ScriptedPage = new ScriptedPage();
    page.tokens = tokens;
    return page;
  }
}

/** The scripted answers available to the feed leaves. */
export class FeedScript {
  communityPages: ScriptedPage[] = [];
  forYouPages: ScriptedPage[] = [];
  communityFailures: string[] = [];
  forYouFailures: string[] = [];

  constructor() {
  }

  nextCommunityPage(): ScriptedPage | undefined {
    return shift(this.communityPages);
  }

  nextForYouPage(): ScriptedPage | undefined {
    return shift(this.forYouPages);
  }
}

function shift(pages: ScriptedPage[]): ScriptedPage | undefined {
  if (pages.length === 0) {
    return undefined;
  }
  const page: ScriptedPage = pages[0];
  pages.shift();
  return page;
}

/* ------------------------------------------------------------------ *
 * The feed content leaf boundary.
 * ------------------------------------------------------------------ */

export class FeedContentService {
  private readonly leaf: ExploreLeaf;
  private readonly script: FeedScript;
  private readonly attempts: Map<string, number> = new Map<string, number>();
  private readonly totals: Map<string, number> = new Map<string, number>();

  constructor(leaf: ExploreLeaf, script: FeedScript) {
    this.leaf = leaf;
    this.script = script;
  }

  /** Number of attempts already issued for a logical scope. */
  attemptsFor(scope: string): number {
    const value: number | undefined = this.attempts.get(scope);
    return value === undefined ? 0 : value;
  }

  /** Records an attempt for a logical scope and returns the new count. */
  private recordAttempt(scope: string): number {
    const next: number = this.attemptsFor(scope) + 1;
    this.attempts.set(scope, next);
    const total: number = this.totals.get(scope);
    this.totals.set(scope, total === undefined ? 1 : total + 1);
    return next;
  }

  /** Requests one Community day. */
  async fetchCommunity(request: CommunityRequest): Promise<CommunityPage> {
    this.recordAttempt(request.scope());
    const effect: ExploreEffect = {
      name: 'communityFeedRequest',
      leaf: 'community_feed',
      source: request.source,
      attempt: request.attempt,
      attemptForLogicalAge: request.attemptForLogicalAge,
      language: request.language,
      date: request.date,
      logicalAge: request.logicalAge,
      surfaces: [FeedTabSurface.COMMUNITY],
      result: 'REQUEST'
    };
    await this.leaf.emit(effect);
    const failure: string = this.script.communityFailures.length > 0 ?
      this.script.communityFailures.shift() as string : '';
    if (failure.length > 0) {
      effect.result = 'ERROR';
      effect.error = failure;
      await this.leaf.emit(effect);
      throw new FeedServiceException(failure);
    }
    const page: ScriptedPage | undefined = this.script.nextCommunityPage();
    const tokens: string[] = page === undefined ? [] : page.tokens;
    const cards: FeedCard[] = parseTokensSafe(tokens, request.logicalAge, request.language);
    effect.result = 'SUCCESS';
    await this.leaf.emit(effect);
    return new CommunityPage(request.logicalAge, request.date, cards, true);
  }

  /** Requests one For You batch. */
  async fetchForYou(request: ForYouRequest): Promise<ForYouPage> {
    this.recordAttempt(request.scope());
    const effect: ExploreEffect = {
      name: 'forYouFeedRequest',
      leaf: 'for_you_feed',
      source: request.source,
      attempt: request.attempt,
      language: request.language,
      date: request.date,
      batch: request.batch,
      surfaces: [FeedTabSurface.FOR_YOU],
      result: 'REQUEST'
    };
    await this.leaf.emit(effect);
    const failure: string = this.script.forYouFailures.length > 0 ? this.script.forYouFailures.shift() as string : '';
    if (failure.length > 0) {
      effect.result = 'ERROR';
      effect.error = failure;
      await this.leaf.emit(effect);
      throw new FeedServiceException(failure);
    }
    const page: ScriptedPage | undefined = this.script.nextForYouPage();
    const tokens: string[] = page === undefined ? [] : page.tokens;
    effect.result = 'SUCCESS';
    await this.leaf.emit(effect);
    return new ForYouPage(request.date, request.language, request.batch, true, tokens);
  }
}

/* ------------------------------------------------------------------ *
 * Script construction from the injected snapshot.
 * ------------------------------------------------------------------ */

/** Reads the scripted editorial and recommendation answers out of a snapshot. */
export function feedScriptFromSnapshot(value: Object | undefined): FeedScript {
  const script: FeedScript = new FeedScript();
  if (value === undefined) {
    return script;
  }
  script.communityPages = pagesFrom(value, ['nextFeaturedFeed', 'nextCommunityFeed', 'communityResponses', 'communityPages']);
  script.forYouPages = pagesFrom(value, ['nextForYouFeed', 'forYouResponses', 'forYouPages', 'nextRecommendations']);
  script.communityFailures = failuresFrom(value, ['communityError', 'communityErrorType', 'nextCommunityError']);
  script.forYouFailures = failuresFrom(value, ['forYouError', 'forYouErrorType', 'nextForYouError']);
  return script;
}

function readAliased(record: Record<string, Object>, keys: string[]): Object | undefined {
  for (let index = 0; index < keys.length; index++) {
    const value: Object | undefined = record[keys[index]];
    if (value !== undefined && value !== null) {
      return value;
    }
  }
  return undefined;
}

function pagesFrom(record: Record<string, Object>, keys: string[]): ScriptedPage[] {
  const value: Object | undefined = readAliased(record, keys);
  if (value === undefined) {
    return [];
  }
  const pages: ScriptedPage[] = [];
  const encoded: string = JSON.stringify(value);
  const parsed: Object | undefined = JSON.parse(encoded) as Object | undefined;
  if (Array.isArray(parsed)) {
    const entries: Object[] = parsed as Object[];
    let multiPage: boolean = false;
    for (let index = 0; index < entries.length; index++) {
      const nested: Object | undefined = JSON.parse(JSON.stringify(entries[index])) as Object | undefined;
      if (nested !== undefined && Array.isArray(nested)) {
        multiPage = true;
        break;
      }
      const nestedRecord: Record<string, Object> | undefined = readRecord(nested);
      if (nestedRecord !== undefined && readAliased(nestedRecord, ['error', 'failure', 'exception']) !== undefined) {
        multiPage = true;
        break;
      }
    }
    if (!multiPage) {
      const tokens: string[] = parseTokensSafe(tokensOf(entries), 0, '');
      return [ScriptedPage.content(tokens)];
    }
    for (let index = 0; index < entries.length; index++) {
      const nested: Object | undefined = JSON.parse(JSON.stringify(entries[index])) as Object | undefined;
      if (nested !== undefined && Array.isArray(nested)) {
        pages.push(ScriptedPage.content(parseTokensSafe(tokensOf(nested as Object[]), 0, '')));
        continue;
      }
      const nestedRecord: Record<string, Object> | undefined = readRecord(nested);
      if (nestedRecord !== undefined) {
        const failure: Object | undefined = readAliased(nestedRecord, ['error', 'failure', 'exception']);
        if (failure !== undefined) {
          pages.push(ScriptedPage.failure(textOf(failure)));
          continue;
        }
        pages.push(ScriptedPage.content(parseTokensSafe(tokensOf([nested]), 0, '')));
        continue;
      }
      pages.push(ScriptedPage.content(parseTokensSafe(tokensOf([nested]), 0, '')));
    }
    return pages;
  }
  const single: Record<string, Object> | undefined = readRecord(parsed);
  if (single !== undefined) {
    const failure: Object | undefined = readAliased(single, ['error', 'failure', 'exception']);
    if (failure !== undefined) {
      return [ScriptedPage.failure(textOf(failure))];
    }
  }
  return [ScriptedPage.content([])];
}

function readRecord(value: Object | undefined): Record<string, Object> | undefined {
  if (value === undefined || value === null) {
    return undefined;
  }
  const encoded: string = JSON.stringify(value);
  if (encoded.length === 0 || encoded.charAt(0) === '[' || encoded.charAt(0) === '"') {
    return undefined;
  }
  const parsed: Object | undefined = JSON.parse(encoded) as Object | undefined;
  if (parsed === undefined || parsed === null || Array.isArray(parsed)) {
    return undefined;
  }
  return parsed as Record<string, Object>;
}

function tokensOf(values: Object[]): string[] {
  const tokens: string[] = [];
  for (let index = 0; index < values.length; index++) {
    const record: Record<string, Object> | undefined = readRecord(values[index]);
    if (record !== undefined) {
      const type: string = textOf(record['type']).trim();
      const identifier: string = textOf(record['id']).trim().length > 0 ?
        textOf(record['id']).trim() : textOf(record['title']).trim();
      if (type.length > 0 || identifier.length > 0) {
        tokens.push(identifier.length > 0 ? `${type}:${identifier}` : type);
      }
      continue;
    }
    const token: string = textOf(values[index]).trim();
    if (token.length > 0) {
      tokens.push(token);
    }
  }
  return tokens;
}

function failuresFrom(record: Record<string, Object>, keys: string[]): string[] {
  const value: Object | undefined = readAliased(record, keys);
  if (value === undefined) {
    return [];
  }
  const encoded: string = JSON.stringify(value);
  const parsed: Object | undefined = JSON.parse(encoded) as Object | undefined;
  if (parsed !== undefined && Array.isArray(parsed)) {
    const entries: Object[] = parsed as Object[];
    const failures: string[] = [];
    for (let index = 0; index < entries.length; index++) {
      const entry: string = textOf(entries[index]).trim();
      if (entry.length > 0) {
        failures.push(entry);
      }
    }
    return failures;
  }
  if (parsed !== undefined && !Array.isArray(parsed)) {
    const single: Record<string, Object> | undefined = readRecord(parsed);
    if (single !== undefined) {
      const nested: Object | undefined = readAliased(single, ['error', 'failure', 'exception', 'name']);
      if (nested !== undefined) {
        const name: string = textOf(nested).trim();
        return name.length > 0 ? [name] : [];
      }
    }
  }
  const name: string = textOf(value).trim();
  return name.length > 0 ? [name] : [];
}

