import { common } from '@kit.AbilityKit';
import { preferences } from '@kit.ArkData';
import { ExploreEffect, ExploreInput, ExploreLeaf } from '../integration/ExplorePageIntegration';
import {
  allCommunityModuleTypes, allForYouModuleTypes, cardTokens, CommunityFeedState, FeedActivityResult,
  FeedCard, feedCardTypeOf, FeedClock, FeedEmptyReason, FeedLoadSource, FeedModule, FeedPhase,
  FeedRecoveryAction, FeedSettingsTarget, FeedTabSurface, feedModulesFromCards, ForYouFeedState,
  HomePreference, HomeTab, homePreferenceOf, homeTabForPreference, homeTabOf, isDayHeader, moduleCardTokens,
  moduleTypes, normalizeDate, systemDate
} from './FeedDomain';
import {
  FeedSnapshot, languagesOfCacheEntry, modulesFromCacheEntry, parseCards, parseCardsWithHeaders, parseModules,
  startsWithDayHeader, withDayHeader
} from './FeedSnapshot';
import {
  CommunityPage, CommunityRequest, feedScriptFromSnapshot, FeedScript, FeedServiceException, FeedContentService,
  ForYouPage, ForYouRequest
} from './FeedContentService';
import { FeedInterestRepository, FeedPreferences, FeedStorageKeys } from './HomeFeedStorage';

/** State handed to the interest editor page. */
export class InterestEditorState {
  initialSelections: string[] = [];
  currentSelections: string[] = [];
  /** True when the editor reports that its selections actually changed. */
  updated: boolean = false;
  /** The result the editor reports, when the host pinned one. */
  pendingResult: number = -1;
  result: number = FeedActivityResult.RESULT_CANCELED;

  constructor() {
  }

  /** True when finishing now would take the personalized refresh path. */
  wouldUpdate(): boolean {
    return this.updated || !sameSelections(this.initialSelections, this.currentSelections);
  }

  toRecord(): Record<string, Object> {
    return {
      'initialSelections': this.initialSelections,
      'currentSelections': this.currentSelections,
      'updated': this.updated,
      'pendingResult': this.pendingResult,
      'result': this.result,
      'wouldUpdate': this.wouldUpdate()
    };
  }
}

function sameSelections(left: string[], right: string[]): boolean {
  if (left.length !== right.length) {
    return false;
  }
  for (let index = 0; index < left.length; index++) {
    if (left[index] !== right[index]) {
      return false;
    }
  }
  return true;
}

/** Snapshot of the content removed by a hide action, kept for the undo that follows it. */
class HideUndo {
  readonly kind: string;
  readonly token: string;
  readonly hideKey: string;
  readonly tab: string;
  readonly communityCards: string[];
  readonly forYouCards: string[];

  constructor(kind: string, token: string, hideKey: string, tab: string, communityCards: string[], forYouCards: string[]) {
    this.kind = kind;
    this.token = token;
    this.hideKey = hideKey;
    this.tab = tab;
    this.communityCards = communityCards;
    this.forYouCards = forYouCards;
  }
}

/**
 * The daily For You result.
 *
 * One entry per feed language, all scoped to a single calendar day. A cached
 * result is only reusable for the same date and the same language, which is what
 * keeps the For You tab stable for a day without going stale across languages.
 */
export class ForYouCache {
  private date: string = '';
  private readonly entries: Map<string, FeedModule[]> = new Map<string, FeedModule[]>();

  dateOf(): string {
    return this.date;
  }

  languages(): string[] {
    return Array.from(this.entries.keys());
  }

  get(language: string): FeedModule[] | undefined {
    return this.entries.get(language);
  }

  set(date: string, language: string, modules: FeedModule[]): void {
    if (this.date !== date) {
      this.date = date;
      this.entries.clear();
    }
    this.entries.set(language, modules);
  }

  /** A cache hit requires both the same calendar day and a payload for the language. */
  isUsable(date: string, language: string): boolean {
    if (this.date !== date) {
      return false;
    }
    const modules: FeedModule[] | undefined = this.entries.get(language);
    return modules !== undefined && modules.length > 0;
  }

  clear(): void {
    this.date = '';
    this.entries.clear();
  }

  toRecord(): Record<string, Object> {
    const byLanguage: Record<string, Object> = {};
    const keys: string[] = Array.from(this.entries.keys());
    for (let index = 0; index < keys.length; index++) {
      const modules: FeedModule[] = this.entries.get(keys[index]) as FeedModule[];
      byLanguage[keys[index]] = moduleCardTokens(modules);
    }
    return {
      'date': this.date,
      'languages': this.languages(),
      'modulesByLanguage': byLanguage,
      'moduleTypesByLanguage': this.moduleTypesByLanguage()
    };
  }

  private moduleTypesByLanguage(): Record<string, Object> {
    const result: Record<string, Object> = {};
    const keys: string[] = Array.from(this.entries.keys());
    for (let index = 0; index < keys.length; index++) {
      const modules: FeedModule[] = this.entries.get(keys[index]) as FeedModule[];
      result[keys[index]] = moduleTypes(modules);
    }
    return result;
  }
}

/**
 * Application owned state for the Home feed.
 *
 * The store owns tab selection, persistence, hidden content, the daily For You
 * cache, pagination, retry and empty state selection. Remote content and
 * analytics are leaf boundaries reached through {@link FeedContentService} and
 * {@link ExploreLeaf}; nothing above this class decides a fetch result on the
 * caller's behalf.
 */
export class LegacyExploreStore {
  private static runtime?: LegacyExploreStore;

  private readonly preferences: FeedPreferences;
  private readonly interestRepository: FeedInterestRepository;
  private readonly content: FeedContentService;
  private readonly clock: FeedClock;
  private readonly leaf: ExploreLeaf;
  private readonly snapshot: FeedSnapshot;
  private readonly script: FeedScript;
  private context?: common.UIAbilityContext;

  private homePreference: HomePreference = HomePreference.COMMUNITY;
  private homeLanguage: string = '';
  private configuredLanguages: string[] = [];
  private primaryConfiguredLanguage: string = '';
  private hiddenCards: string[] = [];
  private hiddenCommunityModules: string[] = [];
  private hiddenForYouModules: string[] = [];
  private interestsList: string[] = [];
  private savedArticles: string[] = [];
  private readingActivity: string[] = [];
  private onboardingComplete: boolean = false;

  private readonly cache: ForYouCache = new ForYouCache();
  private readonly community: CommunityFeedState = new CommunityFeedState();
  private readonly forYou: ForYouFeedState = new ForYouFeedState();
  private readonly editor: InterestEditorState = new InterestEditorState();
  private selectedTab: HomeTab = HomeTab.COMMUNITY;
  private lastActivityResult: number = FeedActivityResult.RESULT_CANCELED;
  private pendingAllModulesOffTarget: string = FeedSettingsTarget.FOR_YOU_MODULES;
  private pendingAllModulesOffConfirmation: boolean = true;
  private communityInFlight: boolean = false;
  private forYouInFlight: boolean = false;
  private undo?: HideUndo;
  private disposed: boolean = false;

  private constructor(store: preferences.Preferences, input: ExploreInput) {
    this.preferences = new FeedPreferences(store);
    this.leaf = input.leaf;
    this.snapshot = new FeedSnapshot(input.state, input.persistence);
    this.script = feedScriptFromSnapshot(this.snapshot.getState());
    this.clock = new FeedClock(this.snapshot.text(['clockDate', 'today', 'currentDate']));
    this.content = new FeedContentService(input.leaf, this.script);
    this.interestRepository = new FeedInterestRepository();
  }

  /**
   * Installs the injected snapshot into durable storage and rebuilds the Home
   * state from it. The durable store is cleared first so a remount never mixes
   * two snapshots together.
   */
  static async create(context: common.UIAbilityContext, input: ExploreInput): Promise<LegacyExploreStore> {
    const store: preferences.Preferences = await preferences.getPreferences(context, 'explore_feed');
    await store.clear();
    await store.put(FeedStorageKeys.SNAPSHOT, JSON.stringify(input.persistence));
    await store.flush();
    const instance: LegacyExploreStore = new LegacyExploreStore(store, input);
    instance.context = context;
    await instance.initialize();
    LegacyExploreStore.runtime = instance;
    return instance;
  }

  /** The store backing the mounted Home surface. */
  static current(): LegacyExploreStore | undefined {
    return LegacyExploreStore.runtime;
  }

  private async initialize(): Promise<void> {
    this.readConfiguration();
    this.hydrateTabs();
    await this.interestRepository.initialize(this.context as common.UIAbilityContext, this.interestsList);
    await this.reloadPersistence();
  }

  /* ---------------------------------------------------------------- *
   * Hydration.
   * ---------------------------------------------------------------- */

  private readConfiguration(): void {
    this.configuredLanguages = this.snapshot.list(['configuredLanguages', 'appLanguages']);
    this.primaryConfiguredLanguage = this.snapshot.text(['primaryConfiguredLanguage', 'primaryLanguage']);
    this.homeLanguage = this.snapshot.text(['homeLanguage', 'persistedHomeLanguage', 'feedLanguage', 'language']);
    this.homePreference = homePreferenceOf(this.snapshot.text(['homePreference', 'preference']));
    this.onboardingComplete = this.snapshot.flag(['onboardingComplete', 'onboarding'], true);
    this.interestsList = this.snapshot.list(['interests', 'persistedInterests', 'savedInterests']);
    this.savedArticles = this.snapshot.list(['savedArticles', 'savedPages']);
    this.readingActivity = this.snapshot.list(['readingHistory', 'recentlyRead', 'readHistory']);
    this.hiddenCards = this.snapshot.list(['hiddenCards', 'persistedHiddenCards']);
    this.hiddenCommunityModules = this.snapshot.list(
      ['hiddenCommunityModules', 'persistedCommunityHiddenModules', 'communityHiddenModules']);
    this.hiddenForYouModules = this.snapshot.list(
      ['hiddenModules', 'persistedHiddenModules', 'hiddenForYouModules', 'forYouHiddenModules']);
    this.pendingAllModulesOffTarget = this.snapshot.text(
      ['pendingAllModulesOffTarget', 'allModulesOffTarget'], `${FeedSettingsTarget.FOR_YOU_MODULES}`);
    this.pendingAllModulesOffConfirmation = this.snapshot.flag(
      ['pendingAllModulesOffConfirmation', 'allModulesOffPending'], true);
  }

  private hydrateTabs(): void {
    const community: Record<string, Object> | undefined = this.snapshot.record(['community', 'communityState']);
    const forYouRecord: Record<string, Object> | undefined = this.snapshot.record(['forYou', 'forYouState']);

    this.community.language = this.communityLanguage(community);
    this.community.date = this.clock.today();
    this.community.phase = this.snapshotText(community, ['phase'], this.community.phase);
    this.community.backingCards = parseCards(this.nested(community, ['cards']), 0, this.community.language);
    this.community.phase = feedPhaseFromText(this.community.phase);
    this.community.pushHistory(this.community.phase);

    const failedAge: number = this.snapshot.number(['failedLogicalAge'], -1);
    this.community.failedLogicalAge = failedAge;
    this.community.nextLogicalAge = failedAge >= 0 ? failedAge : this.community.newestLogicalAge() + 1;
    this.community.inlineError = this.community.phase === FeedPhase.CONTENT_WITH_INLINE_ERROR ||
      this.nestedFlag(community, ['inlineError'], false);
    this.community.retryAvailable = this.snapshot.flag(['retryAvailable'],
      this.community.phase === FeedPhase.ERROR || this.community.phase === FeedPhase.CONTENT_WITH_INLINE_ERROR);

    this.forYou.language = this.forYouLanguage(forYouRecord);
    this.forYou.date = normalizeDate(this.snapshotText(forYouRecord, ['date'], ''), this.clock.today());
    this.forYou.phase = feedPhaseFromText(
      this.snapshot.text(['forYouPhase']) + this.snapshotText(forYouRecord, ['phase'], ''));
    this.forYou.backingModules = this.hydratedForYouModules(forYouRecord);
    this.forYou.failedBatch = this.snapshot.number(['failedBatch'], -1);
    this.forYou.batchIndex = this.forYou.failedBatch >= 0 ? this.forYou.failedBatch : this.snapshot.number(
      ['forYouBatchIndex', 'batchIndex'], 0);
    this.forYou.retryAvailable = this.snapshot.flag(['retryAvailable'],
      this.forYou.phase === FeedPhase.ERROR || this.forYou.phase === FeedPhase.CONTENT_WITH_INLINE_ERROR);

    const tab: HomeTab | undefined = homeTabOf(this.snapshot.text(['selectedTab', 'tab']));
    this.selectedTab = tab === undefined ? homeTabForPreference(this.homePreference) : tab;

    this.restoreCacheFromSnapshot();

    this.editor.initialSelections = this.snapshot.list(['interestEditor', 'initialSelections']);
    this.editor.currentSelections = this.snapshot.list(['interestEditor', 'currentSelections']);
    this.editor.updated = this.snapshot.flag(['interestEditor', 'interestsUpdated'], false);
    this.editor.pendingResult = this.snapshot.number(['interestEditor', 'pendingResult'], -1);

    this.refreshCommunityPresentation();
    this.refreshForYouPresentation();
    this.evaluateCommunityEmptyState();
    this.evaluateForYouEmptyState();
  }

  private communityLanguage(community: Record<string, Object> | undefined): string {
    const language: string = this.snapshotText(community, ['language'], '');
    return language.length > 0 ? language : this.homeLanguage;
  }

  private forYouLanguage(forYouRecord: Record<string, Object> | undefined): string {
    const language: string = this.snapshotText(forYouRecord, ['language'], '');
    return language.length > 0 ? language : this.homeLanguage;
  }

  private hydratedForYouModules(forYouRecord: Record<string, Object> | undefined): FeedModule[] {
    const direct: Object | undefined = this.nested(forYouRecord, ['modules']);
    if (direct !== undefined) {
      return parseModules(direct, this.forYou.language);
    }
    const loose: Object | undefined = this.snapshot.record(['forYouModules']);
    if (loose !== undefined) {
      return parseModules(loose, this.forYou.language);
    }
    const state: Record<string, Object> | undefined = this.snapshot.record(['forYouState']);
    if (state !== undefined) {
      const modules: Object | undefined = this.nested(state, ['modules']);
      if (modules !== undefined) {
        return parseModules(modules, this.forYou.language);
      }
    }
    return [];
  }

  private restoreCacheFromSnapshot(): void {
    const entries: Record<string, Object> | undefined =
      this.snapshot.record(['persistedForYouCache', 'forYouCache']);
    if (entries === undefined) {
      return;
    }
    const date: string = normalizeDate(textField(entries, 'date'), this.clock.today());
    const languages: string[] = languagesOfCacheEntry(entries);
    for (let index = 0; index < languages.length; index++) {
      const modules: FeedModule[] = modulesFromCacheEntry(entries, languages[index]);
      if (modules.length > 0) {
        this.cache.set(date, languages[index], modules);
      }
    }
  }

  private snapshotText(record: Record<string, Object> | undefined, keys: string[], fallback: string): string {
    if (record === undefined) {
      return fallback;
    }
    for (let index = 0; index < keys.length; index++) {
      const value: Object | undefined = record[keys[index]];
      if (value !== undefined && value !== null) {
        return textField(record, keys[index]);
      }
    }
    return fallback;
  }

  private nested(record: Record<string, Object> | undefined, keys: string[]): Object | undefined {
    if (record === undefined) {
      return undefined;
    }
    for (let index = 0; index < keys.length; index++) {
      const value: Object | undefined = record[keys[index]];
      if (value !== undefined && value !== null) {
        return value;
      }
    }
    return undefined;
  }

  private nestedFlag(record: Record<string, Object> | undefined, keys: string[], fallback: boolean): boolean {
    const value: Object | undefined = this.nested(record, keys);
    if (value === undefined) {
      return fallback;
    }
    return textField(record, keys[0]) === 'true';
  }

  /* ---------------------------------------------------------------- *
   * Durable state.
   * ---------------------------------------------------------------- */

  /**
   * Re-reads the durable feed state. Values that durable storage does not hold
   * yet are taken from the injected snapshot and written back, so the choice the
   * reader made is stored by the same flow that reads it back later.
   */
  private async reloadPersistence(): Promise<void> {
    const storedPreference: string = await this.preferences.readText(FeedStorageKeys.HOME_PREFERENCE);
    if (storedPreference.length > 0) {
      this.homePreference = homePreferenceOf(storedPreference);
    } else {
      this.homePreference = homePreferenceOf(this.snapshot.text(['homePreference', 'preference']));
      await this.preferences.writeText(FeedStorageKeys.HOME_PREFERENCE, `${this.homePreference}`);
    }
    const storedLanguage: string = await this.preferences.readText(FeedStorageKeys.HOME_LANGUAGE);
    if (storedLanguage.length > 0) {
      this.homeLanguage = storedLanguage;
    } else {
      this.homeLanguage = this.snapshot.text(['homeLanguage', 'persistedHomeLanguage', 'feedLanguage', 'language']);
      if (this.homeLanguage.length > 0) {
        await this.preferences.writeText(FeedStorageKeys.HOME_LANGUAGE, this.homeLanguage);
      }
    }
    const storedCards: string[] = await this.preferences.readList(FeedStorageKeys.HIDDEN_CARDS);
    if (storedCards.length > 0) {
      this.hiddenCards = storedCards;
    } else {
      this.hiddenCards = this.snapshot.list(['hiddenCards', 'persistedHiddenCards']);
      await this.preferences.writeList(FeedStorageKeys.HIDDEN_CARDS, this.hiddenCards);
    }
    const storedCommunity: string[] = await this.preferences.readList(FeedStorageKeys.HIDDEN_COMMUNITY_MODULES);
    if (storedCommunity.length > 0) {
      this.hiddenCommunityModules = storedCommunity;
    } else {
      this.hiddenCommunityModules = this.snapshot.list(
        ['hiddenCommunityModules', 'persistedCommunityHiddenModules', 'communityHiddenModules']);
      await this.preferences.writeList(FeedStorageKeys.HIDDEN_COMMUNITY_MODULES, this.hiddenCommunityModules);
    }
    const storedForYou: string[] = await this.preferences.readList(FeedStorageKeys.HIDDEN_FOR_YOU_MODULES);
    if (storedForYou.length > 0) {
      this.hiddenForYouModules = storedForYou;
    } else {
      this.hiddenForYouModules = this.snapshot.list(
        ['hiddenModules', 'persistedHiddenModules', 'hiddenForYouModules', 'forYouHiddenModules']);
      await this.preferences.writeList(FeedStorageKeys.HIDDEN_FOR_YOU_MODULES, this.hiddenForYouModules);
    }
    const storedOnboarding: string = await this.preferences.readText(FeedStorageKeys.ONBOARDING_COMPLETE);
    if (storedOnboarding.length > 0) {
      this.onboardingComplete = storedOnboarding === 'true';
    } else {
      await this.preferences.writeText(FeedStorageKeys.ONBOARDING_COMPLETE, `${this.onboardingComplete}`);
    }
    this.interestsList = await this.interestRepository.all();
  }

  /* ---------------------------------------------------------------- *
   * Language.
   * ---------------------------------------------------------------- */

  /** The feed language actually used: the stored one when it is still configured. */
  activeLanguage(): string {
    return this.resolveLanguage(this.homeLanguage);
  }

  private resolveLanguage(stored: string): string {
    if (this.configuredLanguages.length === 0) {
      return stored.length > 0 ? stored : systemDate().length > 0 ? 'en' : 'en';
    }
    if (stored.length > 0 && this.configuredLanguages.indexOf(stored) >= 0) {
      return stored;
    }
    if (this.primaryConfiguredLanguage.length > 0 &&
      this.configuredLanguages.indexOf(this.primaryConfiguredLanguage) >= 0) {
      return this.primaryConfiguredLanguage;
    }
    return this.configuredLanguages[0];
  }

  /** Selects a feed language from the configured app languages and reloads the active tab. */
  async setFeedLanguage(language: string): Promise<void> {
    if (this.configuredLanguages.length > 0 && this.configuredLanguages.indexOf(language) < 0) {
      return;
    }
    if (this.homeLanguage === language) {
      return;
    }
    this.homeLanguage = language;
    await this.preferences.writeText(FeedStorageKeys.HOME_LANGUAGE, language);
    await this.emit({
      name: 'homeLanguageChanged',
      leaf: 'analytics',
      surfaces: [FeedTabSurface.HOME],
      language: language,
      result: language
    });
    await this.reloadActiveTab(FeedLoadSource.LANGUAGE_CHANGED, true);
  }

  /* ---------------------------------------------------------------- *
   * Home surface lifecycle.
   * ---------------------------------------------------------------- */

  /** Rebuilds the surface from durable state and loads the tab the choice selects. */
  async recreateHomeSurface(): Promise<void> {
    await this.reloadPersistence();
    this.undo = undefined;
    const language: string = this.activeLanguage();
    this.homeLanguage = language;
    await this.preferences.writeText(FeedStorageKeys.HOME_LANGUAGE, language);
    const tab: HomeTab = homeTabForPreference(this.homePreference);
    this.community.reset(language, this.clock.today());
    this.forYou.reset(language, this.clock.today());
    this.selectedTab = tab;
    await this.emit({
      name: 'homeSurfaceRecreated',
      leaf: 'analytics',
      surfaces: [FeedTabSurface.HOME],
      language: language,
      result: `${tab}`
    });
    await this.onLoadMore(tab, FeedLoadSource.INITIAL);
  }

  /**
   * Returns to the foreground. An unavailable stored language falls back to a
   * configured one, which resets and reloads the active tab only; the peer tab
   * keeps whatever it was showing until it is selected again.
   */
  async resumeHomeSurface(): Promise<void> {
    await this.reloadPersistence();
    const resolved: string = this.activeLanguage();
    const changed: boolean = resolved !== this.homeLanguage;
    this.homeLanguage = resolved;
    if (changed) {
      await this.preferences.writeText(FeedStorageKeys.HOME_LANGUAGE, resolved);
      await this.emit({
        name: 'homeLanguageResolved',
        leaf: 'analytics',
        surfaces: [FeedTabSurface.HOME],
        language: resolved,
        result: resolved
      });
      await this.reloadActiveTab(FeedLoadSource.LANGUAGE_CHANGED, true);
      return;
    }
    await this.refreshActiveTab(FeedLoadSource.RESUME, false);
  }

  /** Resets the active tab and loads it again. */
  async refreshActiveTab(): Promise<void> {
    await this.refreshActiveTab(FeedLoadSource.REFRESH, true);
  }

  private async refreshActiveTab(source: FeedLoadSource, force: boolean): Promise<void> {
    if (this.tabInFlight(this.selectedTab)) {
      return;
    }
    if (!force && !this.activeTabIsStale()) {
      return;
    }
    this.resetTab(this.selectedTab, this.activeLanguage());
    await this.onLoadMore(this.selectedTab, source);
  }

  /** True when the active tab is showing a result from a previous calendar day. */
  private activeTabIsStale(): boolean {
    if (this.selectedTab === HomeTab.COMMUNITY) {
      if (this.community.phase === FeedPhase.IDLE) {
        return true;
      }
      return this.community.date.length > 0 && this.community.date !== this.clock.today();
    }
    if (this.forYou.phase === FeedPhase.IDLE) {
      return true;
    }
    return this.forYou.date.length > 0 && this.forYou.date !== this.clock.today();
  }

  /** Switches tab. Only an idle, non loading destination is loaded. */
  async selectHomeTab(tab: string): Promise<void> {
    const target: HomeTab | undefined = homeTabOf(tab);
    if (target === undefined) {
      return;
    }
    this.selectedTab = target;
    await this.emit({
      name: 'homeTabSelected',
      leaf: 'analytics',
      surfaces: [surfaceOf(target)],
      language: this.homeLanguage,
      result: `${target}`
    });
    if (this.tabInFlight(target)) {
      return;
    }
    if (this.isIdle(target)) {
      await this.onLoadMore(target, FeedLoadSource.INITIAL);
    }
  }

  /* ---------------------------------------------------------------- *
   * Loading.
   * ---------------------------------------------------------------- */

  /** Retries the failed Community request for the same logical day. */
  async retryCommunityLoad(): Promise<void> {
    await this.onLoadMore(HomeTab.COMMUNITY, FeedLoadSource.RETRY);
  }

  /** Retries the failed Community load-more for the same logical day. */
  async retryCommunityLoadMore(): Promise<void> {
    await this.onLoadMore(HomeTab.COMMUNITY, FeedLoadSource.RETRY_MORE);
  }

  /** Retries the failed For You batch through the same load-more entry point. */
  async retryForYouLoad(): Promise<void> {
    await this.onLoadMore(HomeTab.FOR_YOU, FeedLoadSource.RETRY);
  }

  /** Requests the next logical Community day. */
  async loadCommunityMore(): Promise<void> {
    await this.onLoadMore(HomeTab.COMMUNITY, FeedLoadSource.LOAD_MORE);
  }

  /** Serves the stable daily For You result. */
  async loadForYouMore(): Promise<void> {
    await this.onLoadMore(HomeTab.FOR_YOU, FeedLoadSource.LOAD_MORE);
  }

  /**
   * The single entry point every feed request goes through, including the retry
   * actions bound to the error presentations.
   */
  private async onLoadMore(tab: HomeTab, source: FeedLoadSource): Promise<void> {
    if (this.disposed) {
      return;
    }
    if (tab === HomeTab.COMMUNITY) {
      await this.loadCommunity(source);
      return;
    }
    await this.loadForYou(source);
  }

  private tabInFlight(tab: HomeTab): boolean {
    return tab === HomeTab.COMMUNITY ? this.communityInFlight : this.forYouInFlight;
  }

  private isIdle(tab: HomeTab): boolean {
    return tab === HomeTab.COMMUNITY ? this.community.phase === FeedPhase.IDLE : this.forYou.phase === FeedPhase.IDLE;
  }

  private resetTab(tab: HomeTab, language: string): void {
    if (tab === HomeTab.COMMUNITY) {
      this.community.reset(language, this.clock.today());
      return;
    }
    this.forYou.reset(language, this.clock.today());
  }

  private async reloadActiveTab(source: FeedLoadSource, force: boolean): Promise<void> {
    await this.refreshActiveTab(source, force);
  }

  private async loadCommunity(source: FeedLoadSource): Promise<void> {
    if (this.communityInFlight) {
      return;
    }
    if (this.communityLoadingIsSuppressed()) {
      return;
    }
    this.communityInFlight = true;
    const logicalAge: number = this.community.nextLogicalAge;
    const request: CommunityRequest = new CommunityRequest(
      this.community.language,
      this.clock.today(),
      logicalAge,
      this.content.attemptsFor(`community:${logicalAge}`) + 1,
      this.content.attemptsFor(`community:${logicalAge}`) + 1,
      source);
    this.community.beginLoading(source);
    try {
      const page: CommunityPage = await this.content.fetchCommunity(request);
      this.applyCommunityPage(page);
    } catch (error) {
      this.applyCommunityFailure(errorText(error), logicalAge);
    } finally {
      this.communityInFlight = false;
      this.community.endLoading();
    }
  }

  private communityLoadingIsSuppressed(): boolean {
    if (this.allCommunityModulesHidden()) {
      this.community.retryAvailable = false;
      this.community.inlineError = false;
      this.community.recordPhase(FeedPhase.EMPTY);
      this.evaluateCommunityEmptyState();
      return true;
    }
    return false;
  }

  private applyCommunityPage(page: CommunityPage): void {
    const incoming: FeedCard[] = page.cards;
    const merged: FeedCard[] = mergeCommunityCards(this.community.backingCards, incoming, page.logicalAge, page.language);
    this.community.backingCards = merged;
    this.community.date = page.date;
    // A served page is what advances pagination; a failure never does.
    this.community.nextLogicalAge = page.logicalAge + 1;
    this.community.failedLogicalAge = -1;
    this.community.inlineError = false;
    this.community.retryAvailable = false;
    this.community.stableResultUnused = false;
    this.refreshCommunityPresentation();
    this.evaluateCommunityEmptyState();
    this.community.recordPhase(this.community.cards.length > 0 ? FeedPhase.CONTENT : FeedPhase.EMPTY);
  }

  private applyCommunityFailure(kind: string, logicalAge: number): void {
    this.community.failedLogicalAge = logicalAge;
    this.community.retryAvailable = true;
    this.community.recoveryAction = FeedRecoveryAction.RETRY;
    this.community.secondaryRecoveryAction = FeedRecoveryAction.NONE;
    if (this.community.cards.length > 0) {
      this.community.inlineError = true;
      this.community.recordPhase(FeedPhase.CONTENT_WITH_INLINE_ERROR);
      return;
    }
    this.community.inlineError = false;
    this.community.recordPhase(FeedPhase.ERROR);
    await0();
  }

  private async loadForYou(source: FeedLoadSource): Promise<void> {
    if (this.forYouInFlight) {
      return;
    }
    if (this.forYouLoadingIsSuppressed()) {
      return;
    }
    const language: string = this.forYou.language.length > 0 ? this.forYou.language : this.activeLanguage();
    const date: string = this.clock.today();
    if (source === FeedLoadSource.LOAD_MORE && this.forYou.hasContent() && this.cache.isUsable(this.forYou.date, language)) {
      // The daily result for this language is stable; paging inside a day adds nothing.
      this.forYou.stableResult = true;
      return;
    }
    if (this.cache.isUsable(date, language)) {
      await this.restoreForYouFromCache(date, language, source);
      return;
    }
    this.forYouInFlight = true;
    const batch: number = this.forYou.batchIndex;
    const request: ForYouRequest = new ForYouRequest(
      language, date, batch, this.content.attemptsFor(`for_you:${batch}`) + 1, source);
    this.forYou.beginLoading(source);
    try {
      const page: ForYouPage = await this.content.fetchForYou(request);
      await this.applyForYouPage(page, batch);
    } catch (error) {
      this.applyForYouFailure(errorText(error), batch);
    } finally {
      this.forYouInFlight = false;
      this.forYou.endLoading();
    }
  }

  private forYouLoadingIsSuppressed(): boolean {
    if (this.allForYouModulesHidden()) {
      this.forYou.retryAvailable = false;
      this.forYou.inlineError = false;
      this.forYou.recordPhase(FeedPhase.EMPTY);
      this.evaluateForYouEmptyState();
      return true;
    }
    return false;
  }

  private async restoreForYouFromCache(date: string, language: string, source: FeedLoadSource): Promise<void> {
    const modules: FeedModule[] = this.cache.get(language) as FeedModule[];
    this.forYou.beginLoading(source);
    this.forYou.backingModules = modules;
    this.forYou.language = language;
    this.forYou.date = date;
    this.forYou.failedBatch = -1;
    this.forYou.inlineError = false;
    this.forYou.retryAvailable = false;
    this.forYou.stableResult = true;
    this.forYou.endLoading();
    this.refreshForYouPresentation();
    this.evaluateForYouEmptyState();
    this.forYou.recordPhase(this.forYou.modules.length > 0 ? FeedPhase.CONTENT : FeedPhase.EMPTY);
    await this.emit({
      name: 'forYouCacheRestored',
      leaf: 'analytics',
      surfaces: [FeedTabSurface.FOR_YOU],
      language: language,
      date: date,
      batch: this.forYou.batchIndex,
      result: 'CACHE_HIT'
    });
  }

  private async applyForYouPage(page: ForYouPage, batch: number): Promise<void> {
    this.forYou.backingModules = this.deriveForYouModules(page.language, page.date, page.rankedTitles);
    this.forYou.language = page.language;
    this.forYou.date = page.date;
    // The batch index only advances once a batch has been served.
    this.forYou.batchIndex = batch + 1;
    this.forYou.failedBatch = -1;
    this.forYou.inlineError = false;
    this.forYou.retryAvailable = false;
    this.forYou.stableResult = false;
    this.cache.set(page.date, page.language, this.forYou.backingModules);
    await this.persistCache();
    this.refreshForYouPresentation();
    this.evaluateForYouEmptyState();
    this.forYou.recordPhase(this.forYou.modules.length > 0 ? FeedPhase.CONTENT : FeedPhase.EMPTY);
  }

  private applyForYouFailure(kind: string, batch: number): void {
    this.forYou.failedBatch = batch;
    this.forYou.retryAvailable = true;
    this.forYou.recoveryAction = FeedRecoveryAction.RETRY;
    this.forYou.secondaryRecoveryAction = FeedRecoveryAction.NONE;
    if (this.forYou.modules.length > 0) {
      this.forYou.inlineError = true;
      this.forYou.recordPhase(FeedPhase.CONTENT_WITH_INLINE_ERROR);
      return;
    }
    this.forYou.inlineError = false;
    this.forYou.recordPhase(FeedPhase.ERROR);
  }

  /**
   * Derives the For You recommendation groups from the reader's saved interests,
   * reading activity and saved articles. Titles ranked by the recommendation
   * leaf are folded into the group they belong to; the ranking itself is not.
   */
  private deriveForYouModules(language: string, date: string, rankedTitles: string[]): FeedModule[] {
    const modules: FeedModule[] = [];
    const interests: string[] = titlesForLanguage(this.interestsList, language);
    const reading: string[] = titlesForLanguage(this.readingActivity, language);
    const saved: string[] = titlesForLanguage(this.savedArticles, language);
    appendModule(modules, 'BASED_ON_INTEREST', interests, rankedTitles);
    appendModule(modules, 'BECAUSE_YOU_READ', reading, rankedTitles);
    appendModule(modules, 'CONTINUE_READING', saved, rankedTitles);
    return modules;
  }

  /* ---------------------------------------------------------------- *
   * Presentation.
   * ---------------------------------------------------------------- */

  private refreshCommunityPresentation(): void {
    const visible: FeedCard[] = [];
    const hiddenModules: string[] = this.hiddenCommunityModules;
    for (let index = 0; index < this.community.backingCards.length; index++) {
      const card: FeedCard = this.community.backingCards[index];
      if (this.hiddenCards.indexOf(card.hideKey()) >= 0) {
        continue;
      }
      if (!isDayHeader(card.type) && hiddenModules.indexOf(moduleTypeOf(card)) >= 0) {
        continue;
      }
      visible.push(card);
    }
    this.community.cards = visible;
  }

  private refreshForYouPresentation(): void {
    const presented: FeedModule[] = [];
    const hiddenModules: string[] = this.hiddenForYouModules;
    for (let index = 0; index < this.forYou.backingModules.length; index++) {
      const module: FeedModule = this.forYou.backingModules[index];
      if (hiddenModules.indexOf(module.type) >= 0) {
        continue;
      }
      const cards: FeedCard[] = module.visibleCards(this.hiddenCards);
      if (cards.length === 0) {
        continue;
      }
      presented.push(new FeedModule(module.type, cards));
    }
    this.forYou.modules = presented;
  }

  private evaluateCommunityEmptyState(): void {
    if (this.community.cards.length > 0) {
      this.community.emptyReason = FeedEmptyReason.NONE;
      this.community.recoveryAction = FeedRecoveryAction.NONE;
      this.community.secondaryRecoveryAction = FeedRecoveryAction.NONE;
      return;
    }
    if (this.allCommunityModulesHidden()) {
      this.community.emptyReason = FeedEmptyReason.ALL_MODULES_HIDDEN;
      this.community.recoveryAction = FeedRecoveryAction.OPEN_COMMUNITY_MODULES;
      this.community.secondaryRecoveryAction = FeedRecoveryAction.NONE;
      return;
    }
    this.community.emptyReason = FeedEmptyReason.NO_DATA;
    this.community.recoveryAction = FeedRecoveryAction.RETRY;
    this.community.secondaryRecoveryAction = FeedRecoveryAction.OPEN_COMMUNITY_MODULES;
  }

  private evaluateForYouEmptyState(): void {
    if (this.forYou.modules.length > 0) {
      this.forYou.emptyReason = FeedEmptyReason.NONE;
      this.forYou.recoveryAction = FeedRecoveryAction.NONE;
      this.forYou.secondaryRecoveryAction = FeedRecoveryAction.NONE;
      return;
    }
    if (this.allForYouModulesHidden()) {
      this.forYou.emptyReason = FeedEmptyReason.ALL_MODULES_HIDDEN;
      this.forYou.recoveryAction = FeedRecoveryAction.OPEN_FOR_YOU_MODULES;
      this.forYou.secondaryRecoveryAction = FeedRecoveryAction.NONE;
      return;
    }
    this.forYou.emptyReason = FeedEmptyReason.NO_DATA;
    this.forYou.recoveryAction = FeedRecoveryAction.CUSTOMIZE_INTERESTS;
    this.forYou.secondaryRecoveryAction = FeedRecoveryAction.RETURN_TO_COMMUNITY;
  }

  private allForYouModulesHidden(): boolean {
    const types: string[] = allForYouModuleTypes();
    for (let index = 0; index < types.length; index++) {
      if (this.hiddenForYouModules.indexOf(types[index]) < 0) {
        return false;
      }
    }
    return true;
  }

  private allCommunityModulesHidden(): boolean {
    const types: string[] = allCommunityModuleTypes();
    for (let index = 0; index < types.length; index++) {
      if (this.hiddenCommunityModules.indexOf(types[index]) < 0) {
        return false;
      }
    }
    return true;
  }

  /* ---------------------------------------------------------------- *
   * Module visibility and hidden content.
   * ---------------------------------------------------------------- */

  /** Applies the pending "turn every module off" confirmation for one tab. */
  async confirmAllModulesOff(): Promise<void> {
    if (!this.pendingAllModulesOffConfirmation) {
      return;
    }
    const target: string = this.pendingAllModulesOffTarget.length > 0 ? this.pendingAllModulesOffTarget :
      `${FeedSettingsTarget.FOR_YOU_MODULES}`;
    if (target === FeedSettingsTarget.COMMUNITY_MODULES) {
      this.hiddenCommunityModules = allCommunityModuleTypes();
      await this.persistModuleVisibility();
      this.refreshCommunityPresentation();
      this.evaluateCommunityEmptyState();
      this.community.recordPhase(FeedPhase.EMPTY);
      await this.emit({
        name: 'allModulesHidden',
        leaf: 'analytics',
        surfaces: [FeedTabSurface.SETTINGS],
        result: `${FeedSettingsTarget.COMMUNITY_MODULES}`
      });
      return;
    }
    // Hiding a module filters the backing recommendation groups; the daily cache
    // keeps them so restoring visibility does not need another request.
    this.hiddenForYouModules = allForYouModuleTypes();
    await this.persistModuleVisibility();
    this.refreshForYouPresentation();
    this.evaluateForYouEmptyState();
    this.forYou.recordPhase(FeedPhase.EMPTY);
    await this.emit({
      name: 'allModulesHidden',
      leaf: 'analytics',
      surfaces: [FeedTabSurface.SETTINGS],
      result: `${FeedSettingsTarget.FOR_YOU_MODULES}`
    });
  }

  /** Turns one module on or off in feed settings. */
  async setModuleVisibility(target: string, moduleType: string, visible: boolean): Promise<void> {
    const hidden: string[] = target === FeedSettingsTarget.COMMUNITY_MODULES ?
      this.hiddenCommunityModules : this.hiddenForYouModules;
    const index: number = hidden.indexOf(moduleType);
    if (visible && index >= 0) {
      hidden.splice(index, 1);
    } else if (!visible && index < 0) {
      hidden.push(moduleType);
    }
    await this.persistModuleVisibility();
    this.refreshCommunityPresentation();
    this.refreshForYouPresentation();
    this.evaluateCommunityEmptyState();
    this.evaluateForYouEmptyState();
    await this.emit({
      name: 'moduleVisibilityChanged',
      leaf: 'analytics',
      surfaces: [FeedTabSurface.SETTINGS],
      result: `${target}:${moduleType}:${visible}`
    });
  }

  /** Hides one card. The removal shows immediately and the undo that follows restores it. */
  async hideCard(token: string): Promise<void> {
    const communityIndex: number = indexOfCard(this.community.backingCards, token);
    if (communityIndex >= 0) {
      const card: FeedCard = this.community.backingCards[communityIndex];
      this.undo = new HideUndo('card', card.token(), card.hideKey(), `${HomeTab.COMMUNITY}`,
        cardTokens(this.community.backingCards), moduleCardTokens(this.forYou.backingModules));
      this.addHiddenCard(card.hideKey());
      this.community.backingCards.splice(communityIndex, 1);
      this.refreshCommunityPresentation();
      this.evaluateCommunityEmptyState();
      await this.persistHiddenCards();
      await this.emit({
        name: 'cardHidden',
        leaf: 'analytics',
        surfaces: [FeedTabSurface.COMMUNITY],
        result: card.token()
      });
      return;
    }
    const module: FeedModule | undefined = findModuleWithCard(this.forYou.backingModules, token);
    if (module === undefined) {
      return;
    }
    const cardIndex: number = indexOfCard(module.cards, token);
    const card: FeedCard = module.cards[cardIndex];
    this.undo = new HideUndo('card', card.token(), card.hideKey(), `${HomeTab.FOR_YOU}`,
      cardTokens(this.community.backingCards), moduleCardTokens(this.forYou.backingModules));
    this.addHiddenCard(card.hideKey());
    module.cards.splice(cardIndex, 1);
    this.refreshForYouPresentation();
    this.evaluateForYouEmptyState();
    await this.persistHiddenCards();
    await this.emit({
      name: 'cardHidden',
      leaf: 'analytics',
      surfaces: [FeedTabSurface.FOR_YOU],
      result: card.token()
    });
  }

  /** Hides one module of the active tab. */
  async hideModule(moduleType: string): Promise<void> {
    const onCommunity: boolean = this.communityCardsUseModule(moduleType);
    this.undo = new HideUndo('module', moduleType, moduleType,
      onCommunity ? `${HomeTab.COMMUNITY}` : `${HomeTab.FOR_YOU}`,
      cardTokens(this.community.backingCards), moduleCardTokens(this.forYou.backingModules));
    if (onCommunity) {
      this.addHidden(this.hiddenCommunityModules, moduleType);
    } else {
      this.addHidden(this.hiddenForYouModules, moduleType);
    }
    await this.persistModuleVisibility();
    this.refreshCommunityPresentation();
    this.refreshForYouPresentation();
    this.evaluateCommunityEmptyState();
    this.evaluateForYouEmptyState();
    await this.emit({
      name: 'moduleHidden',
      leaf: 'analytics',
      surfaces: [onCommunity ? FeedTabSurface.COMMUNITY : FeedTabSurface.FOR_YOU],
      result: moduleType
    });
  }

  /** Restores whatever the last hide action removed, at the position it had. */
  async undoLastHide(): Promise<void> {
    const undo: HideUndo | undefined = this.undo;
    if (undo === undefined) {
      return;
    }
    this.undo = undefined;
    this.removeHiddenCard(undo.hideKey);
    if (undo.tab === `${HomeTab.COMMUNITY}`) {
      this.community.backingCards = parseCardsWithHeaders(undo.communityCards, this.community.language);
    } else {
      this.forYou.backingModules = parseModules(undo.forYouCards, this.forYou.language);
    }
    await this.persistHiddenCards();
    await this.persistModuleVisibility();
    this.refreshCommunityPresentation();
    this.refreshForYouPresentation();
    this.evaluateCommunityEmptyState();
    this.evaluateForYouEmptyState();
    await this.emit({
      name: 'hideUndone',
      leaf: 'analytics',
      surfaces: [undo.tab === `${HomeTab.COMMUNITY}` ? FeedTabSurface.COMMUNITY : FeedTabSurface.FOR_YOU],
      result: undo.token
    });
  }

  pendingUndoToken(): string {
    return this.undo === undefined ? '' : this.undo.token;
  }

  private communityCardsUseModule(moduleType: string): boolean {
    const modules: FeedModule[] = feedModulesFromCards(this.community.backingCards);
    for (let index = 0; index < modules.length; index++) {
      if (modules[index].type === moduleType) {
        return true;
      }
    }
    return this.selectedTab === HomeTab.COMMUNITY;
  }

  private addHidden(list: string[], value: string): void {
    if (list.indexOf(value) < 0) {
      list.push(value);
    }
  }

  private addHiddenCard(hideKey: string): void {
    this.addHidden(this.hiddenCards, hideKey);
  }

  private removeHiddenCard(hideKey: string): void {
    const index: number = this.hiddenCards.indexOf(hideKey);
    if (index >= 0) {
      this.hiddenCards.splice(index, 1);
    }
  }

  /* ---------------------------------------------------------------- *
   * Personalization.
   * ---------------------------------------------------------------- */

  /** Opens the interest editor from the For You customize action. */
  async openInterestEditor(): Promise<void> {
    this.editor.initialSelections = this.interestsList.slice();
    this.editor.currentSelections = this.interestsList.slice();
    this.editor.updated = false;
    await this.emit({
      name: 'interestEditorOpened',
      leaf: 'analytics',
      surfaces: [FeedTabSurface.FOR_YOU, FeedTabSurface.INTEREST_EDITOR]
    });
  }

  /** Records the selections the editor is holding. */
  setInterestSelections(selections: string[]): void {
    this.editor.currentSelections = selections;
  }

  interestEditorState(): Record<string, Object> {
    return this.editor.toRecord();
  }

  /**
   * Completes the interest editor. An actual change is written to the interest
   * repository first, then answers RESULT_INTERESTS_UPDATED, which invalidates
   * the personalized content and refreshes For You. An unchanged editor answers
   * RESULT_OK and touches neither the cache nor either tab.
   */
  async finishInterestEditing(): Promise<void> {
    const changed: boolean = this.editor.wouldUpdate();
    if (changed) {
      const selections: string[] = this.editor.currentSelections.length > 0 ?
        this.editor.currentSelections : this.interestsList;
      await this.interestRepository.replaceAll(selections);
      this.interestsList = await this.interestRepository.all();
      this.lastActivityResult = this.editor.pendingResult > 0 ?
        this.editor.pendingResult : FeedActivityResult.RESULT_INTERESTS_UPDATED;
      await this.preferences.writeList(FeedStorageKeys.FOR_YOU_CACHE, []);
      this.cache.clear();
      await this.persistCache();
      await this.emit({
        name: 'interestsPersisted',
        leaf: 'analytics',
        surfaces: [FeedTabSurface.INTEREST_EDITOR],
        result: `${this.interestRepository.storageName()}`
      });
      await this.emit({
        name: 'personalizedContentInvalidated',
        leaf: 'analytics',
        surfaces: [FeedTabSurface.FOR_YOU],
        date: this.clock.today(),
        result: 'INVALIDATED'
      });
      this.editor.result = this.lastActivityResult;
      await this.emit({
        name: 'interestEditorFinished',
        leaf: 'analytics',
        surfaces: [FeedTabSurface.INTEREST_EDITOR],
        value: this.lastActivityResult,
        result: 'RESULT_INTERESTS_UPDATED'
      });
      await this.refreshForYouAfterInterestChange();
      return;
    }
    this.lastActivityResult = this.editor.pendingResult >= 0 && this.editor.pendingResult !== 100 ?
      this.editor.pendingResult : FeedActivityResult.RESULT_OK;
    this.editor.result = this.lastActivityResult;
    await this.emit({
      name: 'interestEditorFinished',
      leaf: 'analytics',
      surfaces: [FeedTabSurface.INTEREST_EDITOR],
      value: this.lastActivityResult,
      result: 'RESULT_OK'
    });
  }

  /**
   * Refreshes For You after its inputs changed. A tab that is showing stale
   * personalized content is reloaded now; an empty one waits for its first load.
   */
  private async refreshForYouAfterInterestChange(): Promise<void> {
    this.forYou.backingModules = [];
    this.forYou.modules = [];
    if (this.forYou.hasContent() || this.forYou.phase === FeedPhase.CONTENT ||
      this.forYou.phase === FeedPhase.CONTENT_WITH_INLINE_ERROR) {
      await this.loadForYou(FeedLoadSource.REFRESH);
      return;
    }
    this.forYou.recordPhase(FeedPhase.IDLE);
  }

  /** Persists the personalization choice made during feed onboarding. */
  async chooseHomePreference(preference: string): Promise<void> {
    this.homePreference = homePreferenceOf(preference);
    this.onboardingComplete = true;
    await this.preferences.writeText(FeedStorageKeys.HOME_PREFERENCE, `${this.homePreference}`);
    await this.preferences.writeText(FeedStorageKeys.ONBOARDING_COMPLETE, 'true');
    this.selectedTab = homeTabForPreference(this.homePreference);
    await this.emit({
      name: 'homePreferenceChosen',
      leaf: 'analytics',
      surfaces: [FeedTabSurface.HOME],
      result: `${this.homePreference}`
    });
    await this.onLoadMore(this.selectedTab, FeedLoadSource.INITIAL);
  }

  onboardingRequired(): boolean {
    return !this.onboardingComplete;
  }

  /* ---------------------------------------------------------------- *
   * Persistence helpers.
   * ---------------------------------------------------------------- */

  private async persistHiddenCards(): Promise<void> {
    await this.preferences.writeList(FeedStorageKeys.HIDDEN_CARDS, this.hiddenCards);
  }

  private async persistModuleVisibility(): Promise<void> {
    await this.preferences.writeList(FeedStorageKeys.HIDDEN_COMMUNITY_MODULES, this.hiddenCommunityModules);
    await this.preferences.writeList(FeedStorageKeys.HIDDEN_FOR_YOU_MODULES, this.hiddenForYouModules);
  }

  private async persistCache(): Promise<void> {
    await this.preferences.writeRecord(FeedStorageKeys.FOR_YOU_CACHE, this.cache.toRecord());
  }

  private async emit(effect: ExploreEffect): Promise<void> {
    try {
      await this.leaf.emit(effect);
    } catch (error) {
      // Observability must never take the feed down.
    }
  }

  /* ---------------------------------------------------------------- *
   * Observation.
   * ---------------------------------------------------------------- */

  currentState(): Record<string, Object> {
    const selectedPhase: FeedPhase = this.selectedTab === HomeTab.COMMUNITY ?
      this.community.phase : this.forYou.phase;
    return {
      'selectedTab': `${this.selectedTab}`,
      'homePreference': `${this.homePreference}`,
      'homeLanguage': this.homeLanguage,
      'language': this.activeLanguage(),
      'configuredLanguages': this.configuredLanguages,
      'primaryConfiguredLanguage': this.primaryConfiguredLanguage,
      'hiddenCards': this.hiddenCards,
      'hiddenModules': unionOf(this.hiddenCommunityModules, this.hiddenForYouModules),
      'hiddenCommunityModules': this.hiddenCommunityModules,
      'hiddenForYouModules': this.hiddenForYouModules,
      'community': this.community.toRecord(),
      'communityPhase': this.community.phase,
      'forYou': this.forYou.toRecord(this.hiddenCards, this.hiddenForYouModules),
      'forYouPhase': this.forYou.phase,
      'phase': selectedPhase,
      'communityLogicalAge': this.community.nextLogicalAge,
      'forYouBatchIndex': this.forYou.batchIndex,
      'clockDate': this.clock.today(),
      'onboardingComplete': this.onboardingComplete,
      'lastActivityResult': this.lastActivityResult,
      'interestEditor': this.editor.toRecord(),
      'interests': this.interestsList,
      'pendingUndo': this.pendingUndoToken(),
      'pendingAllModulesOffConfirmation': this.pendingAllModulesOffConfirmation,
      'pendingAllModulesOffTarget': this.pendingAllModulesOffTarget,
      'communityInFlight': this.communityInFlight,
      'forYouInFlight': this.forYouInFlight
    };
  }

  currentPersistence(): Record<string, Object> {
    return {
      'homePreference': `${this.homePreference}`,
      'homeLanguage': this.homeLanguage,
      'activeLanguage': this.activeLanguage(),
      'configuredLanguages': this.configuredLanguages,
      'primaryConfiguredLanguage': this.primaryConfiguredLanguage,
      'hiddenCards': this.hiddenCards,
      'hiddenCommunityModules': this.hiddenCommunityModules,
      'hiddenForYouModules': this.hiddenForYouModules,
      'forYouCache': this.cache.toRecord(),
      'interests': this.interestsList,
      'interestStorage': this.interestRepository.storageName(),
      'onboardingComplete': this.onboardingComplete,
      'lastActivityResult': this.lastActivityResult,
      'storage': 'preferences:explore_feed',
      'database': `feed_interests.db:${this.interestRepository.storageName()}`,
      'snapshot': this.snapshot.getPersistence()
    };
  }

  /** Releases the store. Any further request is refused rather than half served. */
  dispose(): void {
    this.disposed = true;
    this.undo = undefined;
    if (LegacyExploreStore.runtime === this) {
      LegacyExploreStore.runtime = undefined;
    }
  }
}

/* ------------------------------------------------------------------ *
 * Module helpers.
 * ------------------------------------------------------------------ */

function surfaceOf(tab: HomeTab): string {
  return tab === HomeTab.COMMUNITY ? FeedTabSurface.COMMUNITY : FeedTabSurface.FOR_YOU;
}

function moduleTypeOf(card: FeedCard): string {
  return isDayHeader(card.type) ? '' : `${card.type}`;
}

function errorText(error: Object): string {
  if (error instanceof FeedServiceException) {
    return error.kind;
  }
  const encoded: string = JSON.stringify(error);
  if (encoded.length > 1 && encoded.charAt(0) === '"' && encoded.charAt(encoded.length - 1) === '"') {
    return encoded.substring(1, encoded.length - 1);
  }
  return 'IOException';
}

function textField(record: Record<string, Object>, key: string): string {
  const value: Object | undefined = record[key];
  if (value === undefined || value === null) {
    return '';
  }
  const encoded: string = JSON.stringify(value);
  if (encoded.length > 1 && encoded.charAt(0) === '"' && encoded.charAt(encoded.length - 1) === '"') {
    return encoded.substring(1, encoded.length - 1);
  }
  return encoded;
}

function feedPhaseFromText(value: string): FeedPhase {
  const normalized: string = value.trim().toLowerCase();
  if (normalized.length === 0) {
    return FeedPhase.IDLE;
  }
  if (normalized === FeedPhase.LOADING) {
    return FeedPhase.LOADING;
  }
  if (normalized === FeedPhase.CONTENT) {
    return FeedPhase.CONTENT;
  }
  if (normalized === FeedPhase.CONTENT_WITH_INLINE_ERROR) {
    return FeedPhase.CONTENT_WITH_INLINE_ERROR;
  }
  if (normalized === FeedPhase.EMPTY) {
    return FeedPhase.EMPTY;
  }
  if (normalized === FeedPhase.ERROR) {
    return FeedPhase.ERROR;
  }
  return FeedPhase.IDLE;
}

function unionOf(left: string[], right: string[]): string[] {
  const result: string[] = left.slice();
  for (let index = 0; index < right.length; index++) {
    if (result.indexOf(right[index]) < 0) {
      result.push(right[index]);
    }
  }
  return result;
}

function mergeCommunityCards(existing: FeedCard[], incoming: FeedCard[], logicalAge: number, language: string): FeedCard[] {
  const result: FeedCard[] = existing.slice();
  const body: FeedCard[] = [];
  for (let index = 0; index < incoming.length; index++) {
    if (!isDayHeader(incoming[index].type)) {
      body.push(incoming[index]);
    }
  }
  if (body.length === 0) {
    return result;
  }
  const grouped: FeedCard[] = body;
  if (startsWithDayHeader(result, logicalAge)) {
    let inserted: boolean = false;
    for (let index = 0; index < grouped.length; index++) {
      if (!containsPosition(result, grouped[index]) && !inserted) {
        result.push(new FeedCard(feedCardTypeOf('DAY_HEADER'), `${logicalAge}`, `${logicalAge}`, logicalAge, language));
        inserted = true;
      }
      if (!containsPosition(result, grouped[index])) {
        result.push(grouped[index]);
      }
    }
    return result;
  }
  const header: FeedCard[] = withDayHeader(grouped, logicalAge, language);
  for (let index = 0; index < header.length; index++) {
    if (!containsPosition(result, header[index])) {
      result.push(header[index]);
    }
  }
  return result;
}

function containsPosition(cards: FeedCard[], card: FeedCard): boolean {
  for (let index = 0; index < cards.length; index++) {
    if (cards[index].positionKey() === card.positionKey()) {
      return true;
    }
  }
  return false;
}

function indexOfCard(cards: FeedCard[], token: string): number {
  for (let index = 0; index < cards.length; index++) {
    if (cards[index].token() === token) {
      return index;
    }
  }
  return -1;
}

function findModuleWithCard(modules: FeedModule[], token: string): FeedModule | undefined {
  for (let index = 0; index < modules.length; index++) {
    if (indexOfCard(modules[index].cards, token) >= 0) {
      return modules[index];
    }
  }
  return undefined;
}

/** Language scoped personalisation sources are stored as `language:identifier`. */
function titlesForLanguage(values: string[], language: string): string[] {
  const scoped: string[] = [];
  const plain: string[] = [];
  for (let index = 0; index < values.length; index++) {
    const value: string = values[index];
    const separator: number = value.indexOf(':');
    if (separator <= 0) {
      plain.push(value);
      continue;
    }
    const entryLanguage: string = value.substring(0, separator);
    const identifier: string = value.substring(separator + 1);
    if (identifier.length === 0) {
      continue;
    }
    if (entryLanguage === language) {
      scoped.push(identifier);
    } else {
      plain.push(identifier);
    }
  }
  return scoped.length > 0 ? scoped : plain;
}

function appendModule(modules: FeedModule[], type: string, titles: string[], rankedTitles: string[]): void {
  const seen: string[] = [];
  for (let index = 0; index < rankedTitles.length; index++) {
    const ranked: string = rankedTitles[index];
    if (titles.indexOf(ranked) >= 0 && seen.indexOf(ranked) < 0) {
      seen.push(ranked);
    }
  }
  if (seen.length === 0) {
    return;
  }
  const cards: FeedCard[] = [];
  for (let index = 0; index < seen.length; index++) {
    cards.push(new FeedCard(feedCardTypeOf(type), seen[index], seen[index], 0, ''));
  }
  modules.push(new FeedModule(type, cards));
}

