input.content:
import { common } from '@kit.AbilityKit';
import { router } from '@kit.ArkUI';
import { CallbackExplorePageOwner, ExploreInput, ExplorePageOwner } from '../integration/ExplorePageIntegration';
import {
  FeedEmptyReason, FeedPhase, FeedRecoveryAction, FeedSettingsTarget, FeedTabSurface, numberOf, recordOf,
  textListOf, textOf
} from '../model/FeedDomain';
import { LegacyExploreStore } from '../model/LegacyExploreStore';

class FeedSection {
  readonly type: string;
  readonly cards: string[];

  constructor(type: string, cards: string[]) {
    this.type = type;
    this.cards = cards;
  }
}

function section(state: Record<string, Object>, key: string): Record<string, Object> {
  const record: Record<string, Object> | undefined = recordOf(state[key]);
  return record === undefined ? {} : record;
}

function text(state: Record<string, Object>, key: string): string {
  return textOf(state[key]).trim();
}

function flag(state: Record<string, Object>, key: string): boolean {
  return textOf(state[key]) === 'true';
}

function count(state: Record<string, Object>, key: string): number {
  return numberOf(state[key], 0);
}

function texts(state: Record<string, Object>, key: string): string[] {
  return textListOf(state[key]);
}

function forYouSections(forYou: Record<string, Object>): FeedSection[] {
  const sections: FeedSection[] = [];
  const types: string[] = texts(forYou, 'moduleTypes');
  const flat: string[] = texts(forYou, 'moduleCardTokens');
  let cursor: number = 0;
  for (let index = 0; index < types.length; index++) {
    const cards: string[] = [];
    while (cursor < flat.length) {
      const token: string = flat[cursor];
      if (tokenType(token) !== types[index]) {
        break;
      }
      cards.push(token);
      cursor++;
    }
    sections.push(new FeedSection(types[index], cards));
  }
  return sections;
}

function tokenType(token: string): string {
  const separator: number = token.indexOf(':');
  return separator < 0 ? token : token.substring(0, separator);
}

function tokenTitle(token: string): string {
  const separator: number = token.indexOf(':');
  return separator < 0 ? token : token.substring(separator + 1);
}

/**
 * The Home surface.
 *
 * Community and For You are independent tabs with their own content, paging and
 * presentation state; switching between them only loads a destination that has
 * nothing to show yet. Every presentation is driven by the store, and every
 * action the reader can take here is a store entry point.
 */
@Entry
@Component
struct Index {
  @State selectedTab: string = FeedTabSurface.COMMUNITY;
  @State communityPhase: string = FeedPhase.IDLE;
  @State communityCards: string[] = [];
  @State communityEmptyReason: string = FeedEmptyReason.NONE;
  @State communityRecovery: string = FeedRecoveryAction.NONE;
  @State communityInlineError: boolean = false;
  @State communityRetryAvailable: boolean = false;
  @State forYouPhase: string = FeedPhase.IDLE;
  @State forYouSections: FeedSection[] = [];
  @State forYouEmptyReason: string = FeedEmptyReason.NONE;
  @State forYouRecovery: string = FeedRecoveryAction.NONE;
  @State forYouSecondaryRecovery: string = FeedRecoveryAction.NONE;
  @State forYouRetryAvailable: boolean = false;
  @State forYouStable: boolean = false;
  @State language: string = '';
  @State languages: string[] = [];
  @State undoToken: string = '';
  @State onboardingRequired: boolean = false;
  @State refreshing: boolean = false;
  @State feedSettingsTarget: string = FeedSettingsTarget.COMMUNITY_MODULES;
  private store?: LegacyExploreStore;
  private runtimeOwnerId: string = 'ExploreIndex:' + String(Date.now());

  aboutToAppear(): void {
    this.syncSurface();
  }

  aboutToDisappear(): void {
    this.refreshing = false;
  }

  /** Mirrors the store onto the view. The store stays the single source of truth. */
  private syncSurface(): void {
    const state: Record<string, Object> = this.store === undefined ? {} : this.store.currentState();
    const community: Record<string, Object> = section(state, 'community');
    const forYou: Record<string, Object> = section(state, 'forYou');
    this.selectedTab = text(state, 'selectedTab');
    this.communityPhase = text(community, 'phase');
    this.communityCards = texts(community, 'cards');
    this.communityEmptyReason = text(community, 'emptyReason');
    this.communityRecovery = text(community, 'recoveryAction');
    this.communityInlineError = flag(community, 'inlineError');
    this.communityRetryAvailable = flag(community, 'retryAvailable');
    this.forYouPhase = text(forYou, 'phase');
    this.forYouSections = forYouSections(forYou);
    this.forYouEmptyReason = text(forYou, 'emptyReason');
    this.forYouRecovery = text(forYou, 'recoveryAction');
    this.forYouSecondaryRecovery = text(forYou, 'secondaryRecoveryAction');
    this.forYouRetryAvailable = flag(forYou, 'retryAvailable');
    this.forYouStable = flag(forYou, 'stableResult');
    this.language = text(state, 'language');
    this.languages = texts(state, 'configuredLanguages');
    this.undoToken = text(state, 'pendingUndo');
    this.onboardingRequired = text(state, 'onboardingComplete') !== 'true';
  }

  /**
   * The owner the page host drives. Every host entry point is bound to the same
   * production store entry point the UI itself uses.
   */
  createRuntimeOwner(): ExplorePageOwner {
    return new CallbackExplorePageOwner(
      async (context: common.UIAbilityContext, input: ExploreInput): Promise<void> => {
        this.store = await LegacyExploreStore.create(context, input);
        this.syncSurface();
      },
      async (): Promise<void> => { await this.store?.recreateHomeSurface(); this.syncSurface(); },
      async (tab: string): Promise<void> => { await this.store?.selectHomeTab(tab); this.syncSurface(); },
      async (): Promise<void> => { await this.store?.retryCommunityLoad(); this.syncSurface(); },
      async (): Promise<void> => { await this.store?.retryCommunityLoadMore(); this.syncSurface(); },
      async (): Promise<void> => { await this.store?.resumeHomeSurface(); this.syncSurface(); },
      async (): Promise<void> => { await this.store?.finishInterestEditing(); this.syncSurface(); },
      async (): Promise<void> => { await this.store?.retryForYouLoad(); this.syncSurface(); },
      async (): Promise<void> => { await this.store?.confirmAllModulesOff(); this.syncSurface(); },
      (): Record<string, Object> => this.store === undefined ? {} : this.store.currentState(),
      (): Record<string, Object> => this.store === undefined ? {} : this.store.currentPersistence(),
      (): boolean => this.store !== undefined,
      (): string => this.runtimeOwnerId
    );
  }

  /* ---------------------------------------------------------------- *
   * Reader actions.
   * ---------------------------------------------------------------- */

  private async selectTab(index: number): Promise<void> {
    const tab: string = index === 1 ? FeedTabSurface.FOR_YOU : FeedTabSurface.COMMUNITY;
    if (this.store === undefined || tab === this.selectedTab) {
      return;
    }
    await this.store.selectHomeTab(tab);
    this.syncSurface();
  }

  private async retryCommunity(): Promise<void> {
    if (this.communityInlineError) {
      await this.store?.retryCommunityLoadMore();
    } else {
      await this.store?.retryCommunityLoad();
    }
    this.syncSurface();
  }

  private async retryForYou(): Promise<void> {
    await this.store?.retryForYouLoad();
    this.syncSurface();
  }

  private async loadMoreCommunity(): Promise<void> {
    if (this.communityPhase !== FeedPhase.CONTENT && this.communityPhase !== FeedPhase.CONTENT_WITH_INLINE_ERROR) {
      return;
    }
    await this.store?.loadCommunityMore();
    this.syncSurface();
  }

  private async loadMoreForYou(): Promise<void> {
    if (this.forYouPhase !== FeedPhase.CONTENT && this.forYouPhase !== FeedPhase.CONTENT_WITH_INLINE_ERROR) {
      return;
    }
    await this.store?.loadForYouMore();
    this.syncSurface();
  }

  private async refresh(): Promise<void> {
    this.refreshing = true;
    await this.store?.refreshActiveTab();
    this.refreshing = false;
    this.syncSurface();
  }

  private async hideCard(token: string): Promise<void> {
    await this.store?.hideCard(token);
    this.syncSurface();
  }

  private async hideModule(moduleType: string): Promise<void> {
    await this.store?.hideModule(moduleType);
    this.syncSurface();
  }

  private async undoHide(): Promise<void> {
    await this.store?.undoLastHide();
    this.syncSurface();
  }

  private async choosePreference(preference: string): Promise<void> {
    await this.store?.chooseHomePreference(preference);
    this.syncSurface();
  }

  private async chooseLanguage(language: string): Promise<void> {
    await this.store?.setFeedLanguage(language);
    this.syncSurface();
  }

  private async openSettings(target: string): Promise<void> {
    this.feedSettingsTarget = target;
    router.pushUrl({ url: 'pages/FeedSettings', params: { target: target } });
  }

  private async customizeInterests(): Promise<void> {
    await this.store?.openInterestEditor();
    router.pushUrl({ url: 'pages/InterestEditor' });
  }

  private async returnToCommunity(): Promise<void> {
    await this.selectTab(0);
  }

  /* ---------------------------------------------------------------- *
   * Presentation.
   * ---------------------------------------------------------------- */

  @Builder
  cardRow(token: string) {
    Row({ space: 12 }) {
      Column({ space: 4 }) {
        Text(tokenType(token))
          .fontSize(11)
          .fontColor('#767676')
        Text(tokenTitle(token))
          .fontSize(16)
          .maxLines(2)
      }
      .alignItems(HorizontalAlign.Start)
      .layoutWeight(1)
      Button('Hide')
        .fontSize(12)
        .onClick(() => { this.hideCard(token); })
    }
    .width('100%')
    .padding({ left: 16, right: 16, top: 12, bottom: 12 })
  }

  @Builder
  dayHeaderRow(token: string) {
    Text(tokenTitle(token).length > 0 ? `Day ${tokenTitle(token)}` : 'Day')
      .fontSize(13)
      .fontWeight(FontWeight.Medium)
      .fontColor('#767676')
      .width('100%')
      .padding({ left: 16, right: 16, top: 16, bottom: 8 })
  }

  @Builder
  communityTab() {
    Column() {
      if (this.communityPhase === FeedPhase.LOADING || this.communityPhase === FeedPhase.IDLE) {
        Column({ space: 8 }) {
          LoadingProgress().width(32).height(32)
          Text('Loading Community')
            .fontSize(14)
            .fontColor('#767676')
        }
        .width('100%')
        .layoutWeight(1)
        .justifyContent(FlexAlign.Center)
      } else if (this.communityPhase === FeedPhase.ERROR) {
        Column({ space: 12 }) {
          Text('The Community feed could not be loaded.')
            .fontSize(15)
          Button('Retry').onClick(() => { this.retryCommunity(); })
        }
        .width('100%')
        .layoutWeight(1)
        .justifyContent(FlexAlign.Center)
      } else if (this.communityPhase === FeedPhase.EMPTY) {
        Column({ space: 12 }) {
          Text(this.communityEmptyReason === FeedEmptyReason.ALL_MODULES_HIDDEN ?
            'Every Community module is turned off.' : 'There is no Community content right now.')
            .fontSize(15)
          if (this.communityRecovery === FeedRecoveryAction.OPEN_COMMUNITY_MODULES) {
            Button('Manage modules').onClick(() => { this.openSettings(FeedSettingsTarget.COMMUNITY_MODULES); })
          } else {
            Button('Retry').onClick(() => { this.retryCommunity(); })
          }
        }
        .width('100%')
        .layoutWeight(1)
        .justifyContent(FlexAlign.Center)
      } else {
        Refresh({ refreshing: this.refreshing }) {
          List() {
            ForEach(this.communityCards, (token: string) => {
              ListItem() {
                if (tokenType(token) === FeedPhase.IDLE ? false : tokenType(token) === 'DAY_HEADER') {
                  this.dayHeaderRow(token)
                } else {
                  this.cardRow(token)
                }
              }
            }, (token: string) => token)

            if (this.communityInlineError) {
              ListItem() {
                Column({ space: 8 }) {
                  Text('Could not load more.')
                    .fontSize(13)
                    .fontColor('#c7254e')
                  Button('Retry').fontSize(12).onClick(() => { this.retryCommunity(); })
                }
                .width('100%')
                .padding(16)
              }
            }
          }
          .width('100%')
          .layoutWeight(1)
          .onReachEnd(() => { this.loadMoreCommunity(); })
        }
        .onRefreshing(() => { this.refresh(); })
      }
    }
    .width('100%')
    .layoutWeight(1)
  }

  @Builder
  forYouTab() {
    Column() {
      if (this.forYouPhase === FeedPhase.LOADING || this.forYouPhase === FeedPhase.IDLE) {
        Column({ space: 8 }) {
          LoadingProgress().width(32).height(32)
          Text('Loading For You').fontSize(14).fontColor('#767676')
        }
        .width('100%')
        .layoutWeight(1)
        .justifyContent(FlexAlign.Center)
      } else if (this.forYouPhase === FeedPhase.ERROR) {
        Column({ space: 12 }) {
          Text('The For You feed could not be loaded.')
            .fontSize(15)
          Button('Retry').onClick(() => { this.retryForYou(); })
        }
        .width('100%')
        .layoutWeight(1)
        .justifyContent(FlexAlign.Center)
      } else if (this.forYouPhase === FeedPhase.EMPTY) {
        Column({ space: 12 }) {
          Text(this.forYouEmptyReason === FeedEmptyReason.ALL_MODULES_HIDDEN ?
            'Every For You module is turned off.' : 'Pick some interests to build your For You feed.')
            .fontSize(15)
          if (this.forYouRecovery === FeedRecoveryAction.OPEN_FOR_YOU_MODULES) {
            Button('Manage modules').onClick(() => { this.openSettings(FeedSettingsTarget.FOR_YOU_MODULES); })
          }
          if (this.forYouRecovery === FeedRecoveryAction.CUSTOMIZE_INTERESTS) {
            Button('Customize interests').onClick(() => { this.customizeInterests(); })
          }
          if (this.forYouSecondaryRecovery === FeedRecoveryAction.RETURN_TO_COMMUNITY) {
            Button('Go to Community')
              .type: ButtonType.Normal
              .onClick(() => { this.returnToCommunity(); })
          }
        }
        .width('100%')
        .layoutWeight(1)
        .justifyContent(FlexAlign.Center)
      } else {
        Refresh({ refreshing: this.refreshing }) {
          List() {
            ForEach(this.forYouSections, (section: FeedSection) => {
              ListItem() {
                Column() {
                  Row() {
                    Text(section.type).fontSize(14).fontWeight(FontWeight.Medium).layoutWeight(1)
                    Button('Hide module')
                      .fontSize(12)
                      .onClick(() => { this.hideModule(section.type); })
                  }
                  .width('100%')
                  .padding({ left: 16, right: 16, top: 12 })

                  ForEach(section.cards, (token: string) => {
                    this.cardRow(token)
                  }, (token: string) => token)
                }
                .width('100%')
                .alignItems(HorizontalAlign.Start)
              }
            }, (section: FeedSection) => section.type)

            if (this.forYouStable) {
              ListItem() {
                Text('Showing today’s recommendations.')
                  .fontSize(12)
                  .fontColor('#767676')
                  .padding(16)
              }
            }
          }
          .width('100%')
          .layoutWeight(1)
          .onReachEnd(() => { this.loadMoreForYou(); })
        }
        .onRefreshing(() => { this.refresh(); })
      }
    }
    .width('100%')
    .layoutWeight(1)
  }

  @Builder
  header() {
    Row({ space: 8 }) {
      Text('Wikipedia')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .layoutWeight(1)
      if (this.languages.length > 1) {
        ForEach(this.languages, (language: string) => {
          Button(language)
            .fontSize(12)
            .type: language === this.language ? ButtonType.Normal : ButtonType.Capsule
            .onClick(() => { this.chooseLanguage(language); })
        }, (language: string) => language)
      }
      Button('Settings').fontSize(12).onClick(() => {
        this.openSettings(this.selectedTab === FeedTabSurface.FOR_YOU ?
          FeedSettingsTarget.FOR_YOU_MODULES : FeedSettingsTarget.COMMUNITY_MODULES);
      })
    }
    .width('100%')
    .padding(16)
  }

  @Builder
  undoBar() {
    Row({ space: 12 }) {
      Text(`Removed ${this.undoToken}`)
        .fontSize(13)
        .layoutWeight(1)
      Button('Undo').fontSize(12).onClick(() => { this.undoHide(); })
    }
    .width('100%')
    .padding({ left: 16, right: 16, top: 8, bottom: 8 })
    .backgroundColor('#f1f1f1')
  }

  @Builder
  onboardingGate() {
    Column({ space: 12 }) {
      Text('Welcome to your new Home feed')
        .fontSize(18)
        .fontWeight(FontWeight.Medium)
      Text('Choose the feed you want to land on. You can change it later in settings.')
        .fontSize(13)
        .fontColor('#767676')
      Button('Show me Community').onClick(() => { this.choosePreference(FeedTabSurface.COMMUNITY); })
      Button('Build my For You feed').onClick(() => { this.choosePreference('PERSONALIZED'); })
    }
    .width('100%')
    .padding(24)
  }

  build() {
    Stack({ alignContent: Alignment.Bottom }) {
      Column() {
        this.header()

        if (this.onboardingRequired) {
          this.onboardingGate()
        } else {
          Tabs({ barPosition: BarPosition.Start, index: this.selectedTab === FeedTabSurface.FOR_YOU ? 1 : 0 }) {
            TabContent() {
              this.communityTab()
            }.tabBar('Community')

            TabContent() {
              this.forYouTab()
            }.tabBar('For You')
          }
          .onChange((index: number) => { this.selectTab(index); })
          .layoutWeight(1)
        }
      }
      .width('100%')
      .height('100%')

      if (this.undoToken.length > 0) {
        this.undoBar()
      }
    }
    .width('100%')
    .height('100%')
  }
}

