function forYouSections(forYou: Record<string, Object>): FeedSection[] {
  const sections: FeedSection[] = [];
  const raw: Object[] = arrayOf(forYou['sections']);
  for (let index = 0; index < raw.length; index++) {
    const entry: Record<string, Object> | undefined = recordOf(raw[index]);
    if (entry === undefined) {
      continue;
    }
    sections.push(new FeedSection(text(entry, 'type'), texts(entry, 'cards')));
  }
  return sections;
}

