import { AbilityConstant, UIAbility, Want } from '@kit.AbilityKit';
import { window } from '@kit.ArkUI';
import { LegacyExploreStore } from '../model/LegacyExploreStore';

export default class EntryAbility extends UIAbility {
  onCreate(want: Want, launchParam: AbilityConstant.LaunchParam): void {
  }

  onWindowStageCreate(windowStage: window.WindowStage): void {
    windowStage.loadContent('pages/Index');
  }

  onDestroy(): void {
    // The Home store outlives a single window; releasing it here keeps a torn
    // down surface from answering requests from a half disposed state.
    const store: LegacyExploreStore | undefined = LegacyExploreStore.current();
    if (store !== undefined) {
      store.dispose();
    }
  }
}

