/** Every module type present in a backing card list. */
export function visibleModuleTypes(cards: FeedCard[], hiddenCards: string[], hiddenModules: string[]): string[] {
  return moduleTypes(feedModulesFromCards(cards).filter((module: FeedModule) => {
    if (hiddenModules.indexOf(module.type) >= 0) {
      return false;
    }
    return module.hasVisibleCard(hiddenCards);
  }));
}

function moduleCardKeys(module: FeedModule): string {
  return moduleCardTokens([module]).join('|');
}

/**
 * Describes why a presented module list differs from the backing module list.
 * Backing modules are filtered, never deleted, so this is the record that proves
 * a hide action only changed presentation.
 */
export function filteredBy(
  backing: FeedModule[], presented: FeedModule[], hiddenCards: string[], hiddenModules: string[]
): string[] {
  const reasons: string[] = [];
  for (let index = 0; index < backing.length; index++) {
    if (hiddenModules.indexOf(backing[index].type) >= 0) {
      reasons.push(`${backing[index].type}:module`);
    } else if (moduleCardKeys(backing[index]) !== moduleCardKeys(presented[index])) {
      reasons.push(`${backing[index].type}:card`);
    }
  }
  return reasons;
}

function hiddenModuleNames(
  backing: FeedModule[], presented: FeedModule[], hiddenCards: string[], hiddenModules: string[]
): string[] {
  return filteredBy(backing, presented, hiddenCards, hiddenModules);
}

